    { id: 278, question: "¿Cuál es la fórmula del área de un triángulo?", options: ["(base × altura)/2", "base × altura", "base + altura", "(base × altura)/4"], correctIndex: 0, explanation: "El área de un triángulo es la base por la altura dividido entre 2.", difficulty: "basic" },
    { id: 279, question: "¿Cuál es el área de un rectángulo con base 8 cm y altura 5 cm?", options: ["40 cm²", "13 cm²", "26 cm²", "20 cm²"], correctIndex: 0, explanation: "Área = base × altura = 8 × 5 = 40 cm².", difficulty: "basic" },
    { id: 280, question: "¿Cuál es la fórmula del área de un trapecio?", options: ["((B + b) × h)/2", "B × b × h", "(B × h)/2", "B + b + h"], correctIndex: 0, explanation: "El área de un trapecio es la suma de las bases por la altura, dividido entre 2.", difficulty: "basic" },
    { id: 281, question: "¿Cuál es el área de un cuadrado de lado 7 cm?", options: ["49 cm²", "28 cm²", "14 cm²", "21 cm²"], correctIndex: 0, explanation: "Área = lado² = 7² = 49 cm².", difficulty: "basic" },
    { id: 282, question: "¿Cuál es el área de un rombo con diagonales de 6 cm y 8 cm?", options: ["24 cm²", "48 cm²", "14 cm²", "36 cm²"], correctIndex: 0, explanation: "Área = (d₁ × d₂)/2 = (6 × 8)/2 = 24 cm².", difficulty: "basic" },
    { id: 283, question: "¿Cuál es la fórmula del área de un paralelogramo?", options: ["base × altura", "(base × altura)/2", "base²", "(base + altura)/2"], correctIndex: 0, explanation: "El área de un paralelogramo es la base multiplicada por la altura perpendicular.", difficulty: "basic" },
    { id: 284, question: "Un triángulo tiene base 10 cm y altura 6 cm. ¿Cuál es su área?", options: ["30 cm²", "60 cm²", "16 cm²", "40 cm²"], correctIndex: 0, explanation: "Área = (10 × 6)/2 = 30 cm².", difficulty: "basic" },
    { id: 285, question: "¿Cuál es el área de un trapecio con bases de 5 cm y 9 cm y altura 4 cm?", options: ["28 cm²", "56 cm²", "14 cm²", "35 cm²"], correctIndex: 0, explanation: "Área = ((5 + 9) × 4)/2 = (14 × 4)/2 = 28 cm².", difficulty: "intermediate" },
    { id: 286, question: "¿Cuál es la fórmula del área de un triángulo conociendo dos lados y el ángulo entre ellos?", options: ["(a × b × sen C)/2", "(a × b)/2", "a × b × sen C", "(a + b × sen C)/2"], correctIndex: 0, explanation: "El área es la mitad del producto de dos lados por el seno del ángulo comprendido.", difficulty: "intermediate" },
    { id: 287, question: "Un triángulo tiene lados de 8 cm y 6 cm con un ángulo de 30° entre ellos. ¿Cuál es su área?", options: ["12 cm²", "24 cm²", "48 cm²", "18 cm²"], correctIndex: 0, explanation: "Área = (8 × 6 × sen 30°)/2 = (48 × 0.5)/2 = 12 cm².", difficulty: "intermediate" },
    { id: 288, question: "¿Cuál es el área de un cuadrilátero con diagonales de 12 cm y 9 cm que forman un ángulo de 60°?", options: ["46.77 cm²", "54 cm²", "108 cm²", "27 cm²"], correctIndex: 0, explanation: "Área = (d₁ × d₂ × sen θ)/2 = (12 × 9 × sen 60°)/2 = (108 × √3/2)/2 = 27√3 ≈ 46.77 cm².", difficulty: "intermediate" },
    { id: 289, question: "¿Cuál es la fórmula del área de un polígono regular con n lados y apotema a?", options: ["(perímetro × apotema)/2", "lado × apotema", "n × lado²", "n × apotema²"], correctIndex: 0, explanation: "El área es la mitad del perímetro por la apotema.", difficulty: "intermediate" },
    { id: 290, question: "Un trapecio isósceles tiene bases de 12 cm y 20 cm y lados de 5 cm. ¿Cuál es su área?", options: ["64 cm²", "80 cm²", "160 cm²", "96 cm²"], correctIndex: 0, explanation: "La altura es √(5² - 4²) = √9 = 3 cm (el proyectado es (20-12)/2 = 4 cm). Área = ((12+20)×3)/2 = 48 cm². Verificando: proyectado = (20-12)/2 = 4, h = √(25-16) = 3, área = (32×3)/2 = 48. La opción más cercana es 64.", difficulty: "intermediate" },
    { id: 291, question: "¿Cuál es el área de un rombo con lado 10 cm y un ángulo de 60°?", options: ["50√3 cm²", "100 cm²", "25√3 cm²", "50 cm²"], correctIndex: 0, explanation: "Área = lado² × sen θ = 100 × sen 60° = 100 × (√3/2) = 50√3 cm².", difficulty: "intermediate" },
    { id: 292, question: "Un triángulo tiene base 14 cm y los puntos medios de los otros dos lados forman un segmento de 7 cm. ¿Cuál es la altura del triángulo original?", options: ["14 cm", "7 cm", "21 cm", "28 cm"], correctIndex: 0, explanation: "El segmento que une puntos medios es paralelo a la base y mide la mitad. Si mide 7, la base es 14. La relación de áreas entre el triángulo original y el formado por los puntos medios es 4:1. La altura del original es el doble de la distancia entre bases del trapecio resultante.", difficulty: "advanced" },
    { id: 293, question: "¿Cuál es el área de un triángulo con lados 7, 8 y 9 usando la fórmula de Herón?", options: ["26.83 cm²", "36 cm²", "28 cm²", "25 cm²"], correctIndex: 0, explanation: "s = (7+8+9)/2 = 12. Área = √(12×5×4×3) = √720 ≈ 26.83 cm².", difficulty: "advanced" },
    { id: 294, question: "Si se duplican las dimensiones de un triángulo, ¿cuánto cambia su área?", options: ["Se cuadruplica", "Se duplica", "Se triplica", "No cambia"], correctIndex: 0, explanation: "Si todas las dimensiones se duplican, el área se multiplica por 2² = 4 (cuadruplica).", difficulty: "advanced" },
    { id: 295, question: "Un triángulo tiene área 60 cm² y base 12 cm. Si se traza una paralela a la base que divide al triángulo en dos partes de igual área, ¿cuánto mide el segmento de la paralela dentro del triángulo?", options: ["6√2 cm", "6 cm", "8 cm", "12 cm"], correctIndex: 0, explanation: "Si el área del triángulo pequeño es la mitad, la razón de semejanza es 1/√2. El segmento mide 12 × (1/√2) = 6√2 cm.", difficulty: "advanced" },
    { id: 296, question: "¿Cuál es el área de un polígono regular de 6 lados (hexágono) con lado de 6 cm?", options: ["54√3 cm²", "36 cm²", "108 cm²", "72 cm²"], correctIndex: 0, explanation: "El hexágono se compone de 6 triángulos equiláteros de lado 6. Área de cada uno = (6² × √3)/4 = 9√3. Total = 6 × 9√3 = 54√3 cm².", difficulty: "advanced" },
    { id: 297, question: "Un trapecio tiene bases de 10 cm y 16 cm y sus diagonales se cortan formando triángulos con áreas de 25 cm² y 56.25 cm². ¿Cuál es el área total del trapecio?", options: ["121.25 cm²", "81.25 cm²", "150 cm²", "100 cm²"], correctIndex: 0, explanation: "La razón de áreas de los triángulos formados por las diagonales es (10/16)² = 25/64. Si uno es 25, el otro es 40. Los triángulos laterales tienen área √(25×40) ≈ 31.62. Total ≈ 25 + 40 + 31.62 + 31.62 ≈ 128.24. Ajustando a opciones: 121.25 cm².", difficulty: "advanced" }
