    { id: 305, question: "¿Cuántos puntos tiene una circunferencia?", options: ["Infinitos", "Cuatro", "Dos", "Uno"], correctIndex: 0, explanation: "Una circunferencia es el lugar geométrico de infinitos puntos que están a la misma distancia del centro.", difficulty: "basico" },
    { id: 306, question: "¿Cuál es la ecuación de la circunferencia centrada en el origen con radio 3?", options: ["x² + y² = 9", "x² + y² = 3", "x² + y² = 6", "x² − y² = 9"], correctIndex: 0, explanation: "La ecuación es x² + y² = r² = 3² = 9.", difficulty: "basico" },
    { id: 307, question: "¿Cuántos ejes de simetría tiene una circunferencia?", options: ["Infinitos", "Cuatro", "Dos", "Uno"], correctIndex: 0, explanation: "Cualquier diámetro es un eje de simetría, por lo que hay infinitos.", difficulty: "basico" },
    { id: 308, question: "La ecuación de una parábola con vértice en el origen y foco en (0, 2) es:", options: ["y = (1/8)x²", "y = 8x²", "x² = 8y", "y² = 8x"], correctIndex: 0, explanation: "Foco en (0,2) → p = 2 → x² = 4py = 8y → y = x²/8.", difficulty: "basico" },
    { id: 309, question: "¿Cuántos ejes de simetría tiene una parábola?", options: ["Uno", "Dos", "Cuatro", "Infinitos"], correctIndex: 0, explanation: "Una parábola tiene exactamente un eje de simetría que pasa por el vértice y el foco.", difficulty: "basico" },
    { id: 310, question: "¿Cuál es el radio de la circunferencia x² + y² = 49?", options: ["7", "49", "14", "√7"], correctIndex: 0, explanation: "r² = 49, por lo que r = 7.", difficulty: "basico" },
    { id: 311, question: "Una parábola abre hacia la derecha. Su ecuación es:", options: ["y² = 4px con p > 0", "x² = 4py con p > 0", "y = −ax²", "x = −ay²"], correctIndex: 0, explanation: "Una parábola horizontal que abre a la derecha tiene la forma y² = 4px con p > 0.", difficulty: "basico" },
    { id: 312, question: "¿Cuál es el centro de la circunferencia (x − 3)² + (y + 2)² = 16?", options: ["(3, −2)", "(−3, 2)", "(3, 2)", "(−3, −2)"], correctIndex: 0, explanation: "La forma (x − h)² + (y − k)² = r² tiene centro en (h, k) = (3, −2).", difficulty: "intermedio" },
    { id: 313, question: "Un punto (4, 3) está sobre, dentro o fuera de la circunferencia x² + y² = 25?", options: ["Sobre la circunferencia", "Dentro", "Fuera", "No se puede determinar"], correctIndex: 0, explanation: "4² + 3² = 16 + 9 = 25 = r². El punto está sobre la circunferencia.", difficulty: "intermedio" },
    { id: 314, question: "La parábola y = x² tiene su foco en:", options: ["(0, 1/4)", "(0, 1)", "(1, 0)", "(0, 4)"], correctIndex: 0, explanation: "Para y = x² tenemos 4p = 1 → p = 1/4. El foco está en (0, p) = (0, 1/4).", difficulty: "intermedio" },
    { id: 315, question: "¿Cuál es la distancia del foco a la directriz de la parábola y² = 12x?", options: ["6", "3", "12", "12√3"], correctIndex: 0, explanation: "4p = 12 → p = 3. La distancia foco-directriz es 2p = 6.", difficulty: "intermedio" },
    { id: 316, question: "Dos circunferencias tienen radios 3 y 5, y la distancia entre centros es 10. ¿Cuál es su relación?", options: ["Exteriormente separadas", "Se tocan externamente", "Se cortan", "Interiormente"], correctIndex: 0, explanation: "Si d = 10 > r₁ + r₂ = 8, las circunferencias están exteriormente separadas.", difficulty: "intermedio" },
    { id: 317, question: "La recta y = 2x + 1 corta a la circunferencia x² + y² = 5. ¿Cuántos puntos tiene en común?", options: ["Dos", "Uno", "Ninguno", "Infinitos"], correctIndex: 0, explanation: "Sustituyendo: x² + (2x+1)² = 5 → x² + 4x² + 4x + 1 = 5 → 5x² + 4x − 4 = 0. D = 16 + 80 = 96 > 0, entonces hay dos puntos de intersección.", difficulty: "intermedio" },
    { id: 318, question: "¿Cuál es la ecuación de la circunferencia con extremos del diámetro en (1, 2) y (5, 6)?", options: ["(x−3)² + (y−4)² = 8", "(x−3)² + (y−4)² = 4", "(x−1)² + (y−2)² = 16", "(x−5)² + (y−6)² = 8"], correctIndex: 0, explanation: "Centro = midpoint = (3, 4). Radio = distancia(1,2) a (3,4) = √(4+4) = √8. Ecuación: (x−3)² + (y−4)² = 8.", difficulty: "intermedio" },
    { id: 319, question: "¿Cuál es la ecuación de la directriz de la parábola y² = −16x?", options: ["x = 4", "x = −4", "y = 4", "x = 8"], correctIndex: 0, explanation: "4p = 16 → p = 4. La directriz es x = −p = −4. Pero como abre a la izquierda (negativo), la directriz es x = 4.", difficulty: "intermedio" },
    { id: 320, question: "Una parábola tiene foco en (2, 0) y vértice en el origen. ¿Cuál es su ecuación?", options: ["y² = 8x", "x² = 8y", "y² = 4x", "x² = 4y"], correctIndex: 0, explanation: "p = 2, abre a la derecha: y² = 4px = 4(2)x = 8x.", difficulty: "intermedio" },
    { id: 321, question: "La tangente a la circunferencia x² + y² = 25 en el punto (3, 4) tiene ecuación:", options: ["3x + 4y = 25", "4x + 3y = 25", "3x − 4y = 25", "x + y = 7"], correctIndex: 0, explanation: "La ecuación de la tangente en (x₁, y₁) es xx₁ + yy₁ = r² → 3x + 4y = 25.", difficulty: "avanzado" },
    { id: 322, question: "Una recta con pendiente 2 es tangente a la circunferencia x² + y² = 5. ¿Cuál es su ecuación?", options: ["y = 2x ± 5", "y = 2x ± √5", "y = 2x ± √(5/5)", "y = 2x ± 5√5"], correctIndex: 0, explanation: "Si y = 2x + b es tangente, la distancia del centro (0,0) a la recta es r = √5. |b|/√(1+4) = √5 → |b|/√5 = √5 → |b| = 5 → b = ±5. Pero verificando: √5 ≈ 2.24, y |5|/√5 ≈ 2.24. Entonces b = ±√5. Corrigiendo: |b|/√5 = √5 → |b| = 5. Con la ecuación 2x − y + b = 0: |b|/√(4+1) = √5 → |b| = 5.", difficulty: "avanzado" },
    { id: 323, question: "El segmento focal de una parábola y² = 4px tiene longitud:", options: ["4p", "2p", "p", "8p"], correctIndex: 0, explanation: "El segmento focal (latus rectum) de una parábola tiene longitud |4p|.", difficulty: "avanzado" },
    { id: 324, question: "¿Cuál es el ángulo formado por las tangentes trazadas desde un punto exterior a una circunferencia?", options: ["Depende de la posición del punto", "Siempre 90°", "Siempre 60°", "Siempre 45°"], correctIndex: 0, explanation: "El ángulo entre las tangentes depende de la distancia del punto exterior al centro de la circunferencia.", difficulty: "avanzado" },
    { id: 325, question: "La parábola y² = 8x corta al eje y solo en un punto. ¿Cuál es la distancia de ese punto al foco?", options: ["2", "4", "8", "0"], correctIndex: 0, explanation: "La parábola y² = 8x corta al eje y en (0,0) = vértice. El foco está en (2,0). La distancia del vértice al foco es p = 2.", difficulty: "avanzado" }
