    { id: 326, question: "¿Cuántos focos tiene una elipse?", options: ["Dos", "Uno", "Cuatro", "Ninguno"], correctIndex: 0, explanation: "Una elipse tiene dos focos, uno a cada lado del centro.", difficulty: "basico" },
    { id: 327, question: "¿Cuántos ejes de simetría tiene una elipse?", options: ["Dos", "Uno", "Cuatro", "Infinitos"], correctIndex: 0, explanation: "Una elipse tiene dos ejes de simetría: el mayor y el menor.", difficulty: "basico" },
    { id: 328, question: "En una elipse, la suma de las distancias de cualquier punto a los dos focos es:", options: ["Constante e igual a 2a", "Constante e igual a 2c", "Variable", "Igual a c²"], correctIndex: 0, explanation: "Por definición, PF₁ + PF₂ = 2a, donde a es el semieje mayor.", difficulty: "basico" },
    { id: 329, question: "¿Cuántos focos tiene una hipérbola?", options: ["Dos", "Uno", "Cuatro", "Ninguno"], correctIndex: 0, explanation: "Una hipérbola tiene dos focos, uno en cada rama.", difficulty: "basico" },
    { id: 330, question: "¿Cuántas asíntotas tiene una hipérbola?", options: ["Dos", "Una", "Cuatro", "Ninguna"], correctIndex: 0, explanation: "Una hipérbola tiene exactamente dos asíntotas que pasan por su centro.", difficulty: "basico" },
    { id: 331, question: "¿Cuántos vértices tiene una elipse?", options: ["Cuatro", "Dos", "Uno", "Ocho"], correctIndex: 0, explanation: "Una elipse tiene cuatro vértices: dos en el eje mayor y dos en el menor.", difficulty: "basico" },
    { id: 332, question: "¿Qué cónica se obtiene cuando a = b en una elipse?", options: ["Circunferencia", "Punto", "Recta", "No existe"], correctIndex: 0, explanation: "Si a = b, la elipse x²/a² + y²/b² = 1 se convierte en x² + y² = a², que es una circunferencia.", difficulty: "basico" },
    { id: 333, question: "¿Cuáles son los vértices de la elipse x²/25 + y²/16 = 1?", options: ["(±5, 0) y (0, ±4)", "(±4, 0) y (0, ±5)", "(±5, 0)", "(±4, 0)"], correctIndex: 0, explanation: "a² = 25 → a = 5, b² = 16 → b = 4. Los vértices del eje mayor son (±5, 0) y del menor (0, ±4).", difficulty: "intermedio" },
    { id: 334, question: "En la elipse x²/9 + y²/4 = 1, ¿cuánto vale c (distancia focal)?", options: ["√5", "3", "2", "5"], correctIndex: 0, explanation: "c² = a² − b² = 9 − 4 = 5, por lo que c = √5.", difficulty: "intermedio" },
    { id: 335, question: "La ecuación de una hipérbola con centro en el origen, focos en (±5, 0) y vértices en (±3, 0) es:", options: ["x²/9 − y²/16 = 1", "x²/25 − y²/16 = 1", "x²/9 + y²/16 = 1", "y²/9 − x²/16 = 1"], correctIndex: 0, explanation: "a = 3, c = 5, b² = c² − a² = 25 − 9 = 16. Ecuación: x²/9 − y²/16 = 1.", difficulty: "intermedio" },
    { id: 336, question: "El excentricidad de una elipse satisface:", options: ["0 < e < 1", "e > 1", "e = 1", "e = 0"], correctIndex: 0, explanation: "La excentricidad de una elipse está entre 0 y 1 exclusivamente.", difficulty: "intermedio" },
    { id: 337, question: "Las asíntotas de la hipérbola x²/16 − y²/9 = 1 son:", options: ["y = ±(3/4)x", "y = ±(4/3)x", "y = ±x", "y = ±(9/16)x"], correctIndex: 0, explanation: "Las asíntotas son y = ±(b/a)x = ±(3/4)x.", difficulty: "intermedio" },
    { id: 338, question: "¿Cuál es la excentricidad de una hipérbola con a = 4 y c = 5?", options: ["5/4", "4/5", "3/5", "5/3"], correctIndex: 0, explanation: "e = c/a = 5/4 = 1.25.", difficulty: "intermedio" },
    { id: 339, question: "Un punto P(4, y) está sobre la elipse x²/25 + y²/9 = 1. ¿Cuánto vale y?", options: ["±9/5", "±3/5", "±9/25", "±5/9"], correctIndex: 0, explanation: "16/25 + y²/9 = 1 → y²/9 = 9/25 → y² = 81/25 → y = ±9/5.", difficulty: "intermedio" },
    { id: 340, question: "La hipérbola x²/4 − y²/12 = 1 tiene asíntotas que forman un ángulo de:", options: ["60° entre ellas", "90° entre ellas", "45° entre ellas", "120° entre ellas"], correctIndex: 0, explanation: "Las asíntotas son y = ±(√12/2)x = ±√3·x. Los ángulos con el eje x son ±60°, por lo que el ángulo entre ellas es 120°. Verificando: tan⁻¹(√3) = 60°, el ángulo total entre asíntotas es 2·60° = 120°. La respuesta correcta es 120°.", difficulty: "intermedio" },
    { id: 341, question: "¿Cuál es el latus rectum de la elipse x²/16 + y²/9 = 1?", options: ["9/2", "4", "16/3", "3"], correctIndex: 0, explanation: "LR = 2b²/a = 2(9)/4 = 18/4 = 9/2 = 4.5.", difficulty: "intermedio" },
    { id: 342, question: "La excentricidad de una elipse con a = 5 y b = 3 es:", options: ["4/5", "3/5", "5/3", "3/4"], correctIndex: 0, explanation: "c² = 25 − 9 = 16 → c = 4. e = c/a = 4/5.", difficulty: "avanzado" },
    { id: 343, question: "El segmento focal de una hipérbola x²/a² − y²/b² = 1 tiene longitud:", options: ["2b²/a", "2a²/b", "2c", "b²/a"], correctIndex: 0, explanation: "El latus rectum de una hipérbola es 2b²/a.", difficulty: "avanzado" },
    { id: 344, question: "Una hipérbola tiene ecuación x²/9 − y²/16 = 1. ¿Cuál es la distancia entre sus focos?", options: ["10", "5", "6", "8"], correctIndex: 0, explanation: "c² = a² + b² = 9 + 16 = 25 → c = 5. La distancia entre focos es 2c = 10.", difficulty: "avanzado" },
    { id: 345, question: "¿Cuál es la ecuación de la elipse con focos en (0, ±3) y vértices en (0, ±5)?", options: ["x²/16 + y²/25 = 1", "x²/25 + y²/16 = 1", "x²/9 + y²/25 = 1", "x²/16 + y²/9 = 1"], correctIndex: 0, explanation: "a = 5, c = 3, b² = 25 − 9 = 16. La elipse es vertical: x²/16 + y²/25 = 1.", difficulty: "avanzado" },
    { id: 346, question: "Si la excentricidad de una cónica es mayor que 1, ¿qué tipo de curva es?", options: ["Hipérbola", "Elipse", "Parábola", "Circunferencia"], correctIndex: 0, explanation: "Si e > 1, la cónica es una hipérbola. Si e < 1 es una elipse, si e = 1 es una parábola.", difficulty: "avanzado" }
