      { id: 1, question: "¿Cuál es la hipotenusa de un triángulo rectángulo con catetos 6 y 8?", options: ["10", "12", "14", "16"], correctIndex: 0, explanation: "Aplicando Pitágoras: c = √(6² + 8²) = √(36 + 64) = √100 = 10.", difficulty: "basico" },
      { id: 2, question: "¿Es rectángulo un triángulo con lados 7, 24 y 25?", options: ["Sí, porque 7² + 24² = 25²", "No, porque 7 + 24 > 25", "Sí, porque todos los lados son primos", "No, porque 25² > 7² + 24²"], correctIndex: 0, explanation: "7² + 24² = 49 + 576 = 625 = 25². Se verifica la relación pitagórica, por lo que es rectángulo.", difficulty: "intermedio" },
      { id: 3, question: "¿Cuál es la distancia entre los puntos A(1, 2) y B(4, 6)?", options: ["5", "7", "12", "3√5"], correctIndex: 0, explanation: "d = √((4−1)² + (6−2)²) = √(9 + 16) = √25 = 5.", difficulty: "avanzado" }
    ,
    { id: 347, question: "¿Cuál es la hipotenusa de un triángulo rectángulo con catetos 9 y 12?", options: ["15", "21", "18", "3√7"], correctIndex: 0, explanation: "c = √(9² + 12²) = √(81 + 144) = √225 = 15. Es múltiplo de la terna (3, 4, 5) × 3.", difficulty: "basico" },
    { id: 348, question: "¿Cuál es el cateto de un triángulo rectángulo con hipotenusa 13 y otro cateto 5?", options: ["12", "8", "10", "144"], correctIndex: 0, explanation: "a = √(13² − 5²) = √(169 − 25) = √144 = 12.", difficulty: "basico" },
    { id: 349, question: "¿Es rectángulo un triángulo con lados 9, 12 y 15?", options: ["Sí, porque 9² + 12² = 15²", "No, porque no es la terna 3-4-5", "Sí, porque tiene un lado par", "No, porque 15² > 9² + 12²"], correctIndex: 0, explanation: "81 + 144 = 225 = 15². Se verifica Pitágoras, por lo que es rectángulo.", difficulty: "basico" },
    { id: 350, question: "Un rectángulo tiene base 8 y diagonal 17. ¿Cuál es su altura?", options: ["15", "9", "12", "20"], correctIndex: 0, explanation: "d² = base² + altura² → 17² = 8² + h² → 289 = 64 + h² → h² = 225 → h = 15.", difficulty: "basico" },
    { id: 351, question: "¿Cuál es la longitud de la diagonal de un cuadrado con lado 5?", options: ["5√2", "10", "25", "5"], correctIndex: 0, explanation: "d = l√2 = 5√2, aplicando Pitágoras: d² = 5² + 5² = 50, d = √50 = 5√2.", difficulty: "basico" },
    { id: 352, question: "Un triángulo rectángulo tiene catetos 6 y 8. ¿Cuál es la altura relativa a la hipotenusa?", options: ["24/5", "5", "4", "6"], correctIndex: 0, explanation: "La hipotenusa es 10. h = (a·b)/c = (6·8)/10 = 48/10 = 24/5 = 4.8.", difficulty: "basico" },
    { id: 353, question: "¿Cuál es la distancia entre los puntos A(−3, 0) y B(0, 4)?", options: ["5", "7", "3", "12"], correctIndex: 0, explanation: "d = √((0−(−3))² + (4−0)²) = √(9 + 16) = √25 = 5.", difficulty: "basico" },
    { id: 354, question: "Un triángulo tiene lados 8, 15 y 17. ¿Qué tipo de triángulo es?", options: ["Rectángulo", "Acutángulo", "Obtusángulo", "Equilátero"], correctIndex: 0, explanation: "8² + 15² = 64 + 225 = 289 = 17². Es un triángulo rectángulo.", difficulty: "intermedio" },
    { id: 355, question: "La terna pitagórica (5, 12, 13) verificada es:", options: ["25 + 144 = 169", "25 + 169 = 144", "144 + 169 = 25", "5 + 12 = 13"], correctIndex: 0, explanation: "5² + 12² = 25 + 144 = 169 = 13².", difficulty: "intermedio" },
    { id: 356, question: "Un cable mide 20 m y se extiende desde la parte superior de un poste de 16 m hasta el suelo. ¿A qué distancia del pie del poste está el anclaje?", options: ["12 m", "8 m", "10 m", "15 m"], correctIndex: 0, explanation: "a = √(20² − 16²) = √(400 − 256) = √144 = 12 m.", difficulty: "intermedio" },
    { id: 357, question: "¿Cuánto mide la hipotenusa de un triángulo rectángulo con catetos 20 y 21?", options: ["29", "20.5", "41", "35"], correctIndex: 0, explanation: "c = √(20² + 21²) = √(400 + 441) = √841 = 29.", difficulty: "intermedio" },
    { id: 358, question: "Un avión vuela 300 km Este y luego 400 km Norte. ¿Cuál es su distancia al punto de partida?", options: ["500 km", "700 km", "100 km", "350 km"], correctIndex: 0, explanation: "d = √(300² + 400²) = √(90000 + 160000) = √250000 = 500 km.", difficulty: "intermedio" },
    { id: 359, question: "Si un triángulo tiene lados 7, 24 y 25, ¿cuál es su área?", options: ["84", "175", "56", "300"], correctIndex: 0, explanation: "Es rectángulo (7² + 24² = 25²). A = (7 × 24)/2 = 168/2 = 84.", difficulty: "intermedio" },
    { id: 360, question: "Un triángulo rectángulo tiene cateto de 7 y hipotenusa de 25. ¿Cuál es el otro cateto?", options: ["24", "18", "32", "7√12"], correctIndex: 0, explanation: "b = √(25² − 7²) = √(625 − 49) = √576 = 24.", difficulty: "intermedio" },
    { id: 361, question: "La estela de un avión sobre el suelo forma un triángulo rectángulo con dos carreteras perpendiculares. Si las carreteras se encuentran a 6 km y 8 km del avión, ¿cuánto mide la estela?", options: ["10 km", "14 km", "48 km", "2 km"], correctIndex: 0, explanation: "La estela es la hipotenusa: d = √(6² + 8²) = √(36 + 64) = 10 km.", difficulty: "intermedio" },
    { id: 362, question: "Un triángulo tiene lados 11, 60 y 61. ¿Es rectángulo?", options: ["Sí, porque 11² + 60² = 61²", "No", "Solo si es isósceles", "Solo con información adicional"], correctIndex: 0, explanation: "121 + 3600 = 3721 = 61². Sí es rectángulo.", difficulty: "intermedio" },
    { id: 363, question: "Si se duplican los catetos de un triángulo rectángulo, ¿cómo cambia la hipotenusa?", options: ["Se duplica", "Se cuadruplica", "Se multiplica por √2", "No cambia"], correctIndex: 0, explanation: "Si a → 2a y b → 2b, entonces c' = √(4a² + 4b²) = 2√(a² + b²) = 2c. Se duplica.", difficulty: "avanzado" },
    { id: 364, question: "¿Cuál es la distancia entre los puntos A(1, 2, 3) y B(4, 6, 8)?", options: ["√50", "√14", "5√2", "50"], correctIndex: 0, explanation: "d = √((4−1)² + (6−2)² + (8−3)²) = √(9 + 16 + 25) = √50 = 5√2.", difficulty: "avanzado" },
    { id: 365, question: "En un triángulo rectángulo, si los catetos están en razón 3:5 y la hipotenusa mide √34, ¿cuánto mide el menor cateto?", options: ["3", "5", "√34/2", "6"], correctIndex: 0, explanation: "Si a = 3k y b = 5k: 9k² + 25k² = 34 → 34k² = 34 → k = 1. El menor es 3(1) = 3.", difficulty: "avanzado" },
    { id: 366, question: "Un triángulo rectángulo tiene un cateto de 10 y la proyección de ese cateto sobre la hipotenusa mide 6. ¿Cuánto mide la hipotenusa?", options: ["50/3", "20/3", "15", "100/6"], correctIndex: 0, explanation: "Por las relaciones de la métrica en el triángulo rectángulo: a² = c·p, donde p es la proyección. 100 = c·6 → c = 100/6 = 50/3.", difficulty: "avanzado" },
    { id: 367, question: "La diagonal de un cubo mide 10 cm. ¿Cuánto mide la arista del cubo?", options: ["10/√3", "10√3", "5√2", "10/3"], correctIndex: 0, explanation: "d = a√3 → 10 = a√3 → a = 10/√3 = 10√3/3.", difficulty: "avanzado" }
  ,
    { id: 300, question: "¿Qué necesitas para aplicar el criterio LLL en dos triángulos?", options: ["Tres lados iguales respectivamente", "Dos ángulos iguales", "Un lado y dos ángulos", "Dos lados y un ángulo"], correctIndex: 0, explanation: "El criterio LLL establece que dos triángulos son congruentes si sus tres lados correspondientes son iguales.", difficulty: "basico" },
    { id: 301, question: "¿Qué significa que dos triángulos son congruentes?", options: ["Tienen la misma forma y el mismo tamaño", "Solo tienen la misma forma", "Tienen la misma área pero diferente forma", "Solo tienen un lado igual"], correctIndex: 0, explanation: "Triángulos congruentes son exactamente iguales: mismos lados, mismos ángulos y misma área.", difficulty: "basico" },
    { id: 302, question: "Si AB = DE, BC = EF y AC = DF, ¿qué criterio de congruencia aplica?", options: ["LLL", "LAL", "ALA", "AAA"], correctIndex: 0, explanation: "Cuando los tres pares de lados correspondientes son iguales, se usa el criterio LLL.", difficulty: "basico" },
    { id: 303, question: "¿Cuántos lados y ángulos corresponden en el criterio LAL?", options: ["Dos lados y un ángulo comprendido", "Un lado y dos ángulos", "Dos ángulos y un lado", "Tres lados"], correctIndex: 0, explanation: "LAL significa Lado-Ángulo-Lado: dos lados y el ángulo comprendido entre ellos deben ser iguales.", difficulty: "basico" },
    { id: 304, question: "En el criterio ALA, ¿dónde se ubica el lado?", options: ["Entre los dos ángulos conocidos", "Opuesto al ángulo mayor", "Adyacente a un solo ángulo", "No importa su posición"], correctIndex: 0, explanation: "En ALA el lado está comprendido entre los dos ángulos.", difficulty: "basico" },
    { id: 305, question: "¿El criterio AAA garantiza congruencia entre triángulos?", options: ["No, solo garantiza semejanza", "Sí, siempre", "Solo en triángulos rectángulos", "Solo si son equiláteros"], correctIndex: 0, explanation: "AAA no prueba congruencia, solo semejanza. Los triángulos pueden tener los mismos ángulos pero diferentes tamaños.", difficulty: "basico" },
    { id: 306, question: "¿Cuál es la diferencia entre congruencia y semejanza?", options: ["La congruencia requiere igualdad exacta, la semejanza solo igualdad de forma", "Son lo mismo", "La semejanza es más estricta", "La congruencia solo aplica a rectángulos"], correctIndex: 0, explanation: "En congruencia las figuras son idénticas en tamaño y forma. En semejanza tienen la misma forma pero pueden diferir en tamaño.", difficulty: "basico" },
    { id: 307, question: "Si dos triángulos rectángulos tienen la hipotenusa y un cateto iguales, ¿qué criterio se aplica?", options: ["HL (caso especial de LAL)", "LLL", "ALA", "AAA"], correctIndex: 0, explanation: "El criterio hipotenusa-cateto es un caso particular de LAL para triángulos rectángulos.", difficulty: "intermedio" },
    { id: 308, question: "¿Por qué el criterio SSA no garantiza congruencia?", options: ["Puede producir dos triángulos distintos", "Nunca funciona", "Solo funciona en rectángulos", "Siempre produce un solo triángulo"], correctIndex: 0, explanation: "El caso SSA puede generar dos triángulos diferentes cuando el ángulo es agudo y el lado opuesto es menor que el otro lado dado.", difficulty: "intermedio" },
    { id: 309, question: "Si ΔABC ≅ ΔDEF, ¿qué relación es correcta?", options: ["AB = DE, ∠B = ∠E y BC = EF", "Solo AB = DE", "Solo ∠A = ∠D", "El área de ABC es mayor"], correctIndex: 0, explanation: "Si los triángulos son congruentes, todos sus elementos correspondientes son iguales.", difficulty: "intermedio" },
    { id: 310, question: "¿Qué criterio se usa si conoces dos ángulos y un lado NO comprendido?", options: ["AAL (caso de ALA)", "LLL", "LAL", "Solo AAA"], correctIndex: 0, explanation: "Si conoces dos ángulos, automáticamente conoces el tercero, y con un lado puedes llegar a ALA.", difficulty: "intermedio" },
    { id: 311, question: "¿Cuántos datos mínimo se necesitan para determinar un triángulo de forma única?", options: ["Tres datos, incluyendo al menos un lado", "Dos datos", "Cuatro datos", "Un solo lado"], correctIndex: 0, explanation: "Se necesitan al menos tres elementos, y uno debe ser un lado para evitar escalas distintas.", difficulty: "intermedio" },
    { id: 312, question: "¿Qué condiciones hacen que el caso SSA sea seguro?", options: ["Cuando el ángulo es recto o obtuso", "Cuando ambos lados son iguales", "Siempre es ambiguo", "Cuando el ángulo es muy pequeño"], correctIndex: 0, explanation: "El caso SSA es seguro cuando el ángulo dado es recto (HL) o obtuso.", difficulty: "intermedio" },
    { id: 313, question: "Si dos triángulos tienen dos ángulos y el lado opuesto a uno de ellos iguales, ¿son congruentes?", options: ["Sí, por AAL", "Solo son semejantes", "No hay suficiente información", "Solo si el lado es el mayor"], correctIndex: 0, explanation: "Con dos ángulos iguales, el tercero también es igual. Con un lado dado se demuestra congruencia por AAL.", difficulty: "intermedio" },
    { id: 314, question: "¿Qué relación tiene el criterio HL con el criterio LAL?", options: ["HL es un caso particular de LAL para triángulos rectángulos", "Son completamente distintos", "HL reemplaza a LAL en todos los casos", "No tienen relación"], correctIndex: 0, explanation: "En un triángulo rectángulo, la hipotenusa y un cateto son dos lados, y el ángulo recto está comprendido entre ellos.", difficulty: "intermedio" },
    { id: 315, question: "Si ΔPQR ≅ ΔXYZ, ¿cuál es el ángulo correspondiente de ∠R?", options: ["∠Z", "∠X", "∠Y", "Depende del tamaño"], correctIndex: 0, explanation: "En la congruencia ΔPQR ≅ ΔXYZ, los vértices se corresponden en orden: P↔X, Q↔Y, R↔Z.", difficulty: "avanzado" },
    { id: 316, question: "Demuestre que la mediana de un triángulo isósceles es también bisectriz y altura. ¿Qué criterio se usa?", options: ["LAL para probar que los triángulos formados son congruentes", "Solo LLL", "Solo ALA", "No se puede demostrar"], correctIndex: 0, explanation: "Los dos triángulos formados tienen dos lados iguales y el ángulo comprendido entre ellos, verificándose LAL.", difficulty: "avanzado" },
    { id: 317, question: "¿Cuál es la condición para que dos triángulos rectángulos con hipotenusa y un cateto iguales sean congruentes?", options: ["El cateto y la hipotenusa determinan el tercer lado por Pitágoras, aplicando LLL", "Solo necesitan tener la hipotenusa igual", "Se requiere un ángulo adicional", "Debe ser el cateto mayor"], correctIndex: 0, explanation: "Conocer la hipotenusa y un cateto permite calcular el otro con Pitágoras, determinando los tres lados.", difficulty: "avanzado" },
    { id: 318, question: "Si dos triángulos tienen dos lados y el área iguales, ¿son congruentes?", options: ["No, pueden tener la misma área con diferente ángulo comprendido", "Sí, siempre", "Solo si son rectángulos", "Solo si son isósceles"], correctIndex: 0, explanation: "Dos lados iguales con la misma área no determinan un ángulo único, ya que el seno del ángulo puede tener dos valores.", difficulty: "avanzado" },
    { id: 319, question: "En un paralelogramo ABCD con diagonal AC, ¿qué criterio prueba que ΔABC ≅ ΔCDA?", options: ["LLL, ya que AB = CD, BC = DA y AC es compartida", "ALA", "Solo LAL", "No son congruentes"], correctIndex: 0, explanation: "En un paralelogramo, los lados opuestos son iguales y la diagonal es compartida, por lo que LLL demuestra la congruencia.", difficulty: "avanzado" },
    { id: 320, question: "¿Qué se puede afirmar si dos triángulos tienen dos ángulos y el lado opuesto a uno de ellos iguales?", options: ["Son congruentes por AAL, ya que el tercer ángulo también es igual", "Solo son semejantes", "No hay suficiente información", "Solo son congruentes si el lado es el mayor"], correctIndex: 0, explanation: "Con dos ángulos iguales el tercero también es igual, y con un lado dado se demuestra congruencia por AAL.", difficulty: "avanzado" }
