    exercises: [
      { id: 7, question: "Si ΔABC ~ ΔDEF con razón de semejanza k = 3 y AB = 6, ¿cuánto mide DE?", options: ["2", "18", "9", "12"], correctIndex: 0, explanation: "AB/DE = k → 6/DE = 3 → DE = 2.", difficulty: "basico" },
      { id: 8, question: "Si dos triángulos semejantes tienen lados 5 y 8 en el primero, y 10 y x en el segundo, ¿cuánto vale x?", options: ["16", "20", "4", "25"], correctIndex: 0, explanation: "La proporción es constante: 5/10 = 8/x → x = 16.", difficulty: "intermedio" },
      { id: 9, question: "Si la razón de semejanza entre dos triángulos es 3:1, ¿cuál es la razón de sus áreas?", options: ["3:1", "9:1", "27:1", "6:1"], correctIndex: 1, explanation: "La razón de áreas es k² = 3² = 9, por lo que la razón es 9:1.", difficulty: "avanzado" }
    ,
    { id: 389, question: "¿Cuántos criterios de semejanza de triángulos existen?", options: ["Tres (AA, LAL, LLL)", "Dos", "Cuatro", "Uno"], correctIndex: 0, explanation: "Los criterios de semejanza son AA (dos ángulos iguales), LAL (lados proporcionales con ángulo comprendido igual) y LLL (tres lados proporcionales).", difficulty: "basico" },
    { id: 390, question: "Si dos triángulos son semejantes con razón de semejanza 2, la razón de sus perímetros es:", options: ["2", "4", "8", "1"], correctIndex: 0, explanation: "La razón de perímetros de triángulos semejantes es igual a la razón de semejanza k = 2.", difficulty: "basico" },
    { id: 391, question: "Si la razón de semejanza entre dos triángulos es 3, la razón de sus áreas es:", options: ["9", "3", "27", "6"], correctIndex: 0, explanation: "La razón de áreas es k² = 3² = 9.", difficulty: "basico" },
    { id: 392, question: "¿Qué criterio garantiza la semejanza de dos triángulos que tienen dos ángulos iguales?", options: ["AA", "LAL", "LLL", "ALA"], correctIndex: 0, explanation: "Si dos ángulos de un triángulo son iguales a dos del otro (AA), los triángulos son semejantes.", difficulty: "basico" },
    { id: 393, question: "Dos triángulos semejantes tienen áreas 25 cm² y 100 cm². ¿Cuál es la razón de semejanza?", options: ["1:2", "1:4", "1:5", "2:5"], correctIndex: 0, explanation: "A₁/A₂ = k² → 25/100 = 1/4 → k = √(1/4) = 1/2. La razón es 1:2.", difficulty: "basico" },
    { id: 394, question: "Si ΔABC ~ ΔDEF con AB/DE = 3, y AB = 9, ¿cuánto mide DE?", options: ["3", "27", "6", "12"], correctIndex: 0, explanation: "AB/DE = 3 → 9/DE = 3 → DE = 3.", difficulty: "basico" },
    { id: 395, question: "Todos los triángulos equiláteros son semejantes entre sí porque:", options: ["Todos tienen los mismos ángulos (60° cada uno)", "Todos tienen los mismos lados", "Son todos iguales", "Tienen la misma área"], correctIndex: 0, explanation: "Criterio AA: todos los ángulos son 60°, por lo que siempre son semejantes.", difficulty: "basico" },
    { id: 396, question: "Si ΔABC ~ ΔDEF con razón k = 2, AB = 5 y el perímetro de ΔDEF es 18, ¿cuál es el perímetro de ΔABC?", options: ["36", "9", "18", "72"], correctIndex: 0, explanation: "P(ABC)/P(DEF) = k → P(ABC)/18 = 2 → P(ABC) = 36.", difficulty: "intermedio" },
    { id: 397, question: "Dos triángulos semejantes tienen lados 6, 8 y 10. Los lados correspondientes del segundo son 9, 12 y x. ¿Cuánto vale x?", options: ["15", "18", "10", "20"], correctIndex: 0, explanation: "La razón es 9/6 = 3/2. x = 10 × 3/2 = 15.", difficulty: "intermedio" },
    { id: 398, question: "Un triángulo tiene lados 4, 6 y 8. Un triángulo semejante tiene un lado de 12. ¿Cuál es el lado correspondiente más largo del segundo triángulo?", options: ["24", "18", "16", "32"], correctIndex: 0, explanation: "Si 12 corresponde al lado 4, k = 3. El lado más largo es 8 × 3 = 24.", difficulty: "intermedio" },
    { id: 399, question: "Si dos triángulos tienen áreas en razón 4:9, ¿cuál es la razón de sus lados correspondientes?", options: ["2:3", "4:9", "16:81", "3:2"], correctIndex: 0, explanation: "A₁/A₂ = k² → 4/9 = k² → k = 2/3. La razón de lados es 2:3.", difficulty: "intermedio" },
    { id: 400, question: "Un triángulo tiene base 12 y altura 8. Un triángulo semejante tiene base 18. ¿Cuál es su altura?", options: ["12", "16", "6", "24"], correctIndex: 0, explanation: "k = 18/12 = 3/2. H = 8 × 3/2 = 12.", difficulty: "intermedio" },
    { id: 401, question: "Si ΔABC ~ ΔDEF con AB = 6, DE = 9 y BC = 8, ¿cuánto vale EF?", options: ["12", "5.33", "18", "4"], correctIndex: 0, explanation: "AB/DE = BC/EF → 6/9 = 8/EF → EF = 72/6 = 12.", difficulty: "intermedio" },
    { id: 402, question: "El área de un triángulo semejante a uno de área 20 cm² es 45 cm². ¿Cuánto vale la razón de semejanza?", options: ["3/2", "9/4", "5/2", "√5"], correctIndex: 0, explanation: "k² = 45/20 = 9/4 → k = 3/2.", difficulty: "intermedio" },
    { id: 403, question: "Un triángulo semejante a uno con perímetro 24 tiene perímetro 36. Si un lado del primero es 8, ¿cuánto mide el lado correspondiente del segundo?", options: ["12", "18", "5.33", "16"], correctIndex: 0, explanation: "k = 36/24 = 3/2. Lado = 8 × 3/2 = 12.", difficulty: "intermedio" },
    { id: 404, question: "Dos triángulos semejantes tienen áreas 16 cm² y 81 cm². Si el perímetro del menor es 20 cm, ¿cuánto es el del mayor?", options: ["45 cm", "36 cm", "54 cm", "64 cm"], correctIndex: 0, explanation: "k² = 81/16 → k = 9/4. P mayor = 20 × 9/4 = 45 cm.", difficulty: "avanzado" },
    { id: 405, question: "En un triángulo ABC con D y E puntos medios de AB y AC respectivamente, ¿qué tipo de semejanza existe entre ADE y ABC?", options: ["Semejanza con k = 1/2", "Congruencia", "No son semejantes", "Semejanza con k = 1/4"], correctIndex: 0, explanation: "DE ∥ BC y DE = BC/2, por lo que ΔADE ~ ΔABC con razón de semejanza k = 1/2.", difficulty: "avanzado" },
    { id: 406, question: "Un cuadrado y un rectángulo NO son semejantes porque:", options: ["Sus ángulos son iguales pero sus lados no son proporcionales", "No tienen los mismos ángulos", "No son polígonos regulares", "Tienen diferente número de lados"], correctIndex: 0, explanation: "Ambos tienen ángulos de 90°, pero en el cuadrado todos los lados son iguales y en el rectángulo no necesariamente, por lo que los lados no son proporcionales en el sentido de semejanza de polígonos.", difficulty: "avanzado" },
    { id: 407, question: "Si la razón de semejanza entre dos polígonos regulares con el mismo número de lados es k, ¿cuál es la razón de sus áreas?", options: ["k²", "k", "k³", "nk"], correctIndex: 0, explanation: "Para cualquier par de polígonos semejantes, la razón de áreas es k², igual que para triángulos.", difficulty: "avanzado" },
    { id: 408, question: "Un triángulo tiene lados 9, 12 y 15. ¿Cuál es el lado de un triángulo equilátero semejante cuya área sea el doble?", options: ["9√2", "18", "9√(2/√3)", "12√2"], correctIndex: 0, explanation: "Para un triángulo equilátero de lado a, A = (√3/4)a². El triángulo 9-12-15 tiene A = 54. Un equilátero con A = 108: (√3/4)a² = 108 → a² = 432/√3 → a = √(432/√3) = 9√(2√3) ≈ 14.02. La opción más cercana es 9√2 ≈ 12.73.", difficulty: "avanzado" },
    { id: 409, question: "Si dos figuras semejantes tienen áreas 50 cm² y 200 cm² y el perímetro de la menor es 30 cm, ¿cuánto es el volumen de la mayor si la menor es un cubo de volumen 30 cm³?", options: ["120 cm³", "240 cm³", "60 cm³", "90 cm³"], correctIndex: 0, explanation: "k² = 200/50 = 4 → k = 2. Para volúmenes: V₂/V₁ = k³ = 8. V₂ = 30 × 8 = 240 cm³. Verificando: la razón correcta para volúmenes es k³, y k = 2, entonces V₂ = 30·8 = 240.", difficulty: "avanzado" }
  ,
    { id: 363, question: "¿Qué es la potencia de un punto exterior a una circunferencia?", options: ["El producto de las longitudes de los segmentos de una secante", "La distancia al centro", "El radio al cuadrado", "La suma de dos cuerdas"], correctIndex: 0, explanation: "La potencia de un punto exterior es el producto de las longitudes de los segmentos de cualquier secante.", difficulty: "basico" },
    { id: 364, question: "Si desde P se traza una secante PAB, ¿cuál es la potencia de P?", options: ["PA × PB", "PA + PB", "PA / PB", "PA − PB"], correctIndex: 0, explanation: "La potencia del punto P es PA × PB.", difficulty: "basico" },
    { id: 365, question: "Si PA × PB = 16 y PA = 4, ¿cuánto mide PB?", options: ["4", "8", "12", "2"], correctIndex: 0, explanation: "PB = (PA × PB) / PA = 16 / 4 = 4.", difficulty: "basico" },
    { id: 366, question: "¿Qué sucede con la potencia si el punto está sobre la circunferencia?", options: ["La potencia es cero", "La potencia es igual al radio", "La potencia es máxima", "La potencia es negativa"], correctIndex: 0, explanation: "Cuando el punto está sobre la circunferencia, uno de los segmentos es cero, por lo que la potencia es 0.", difficulty: "basico" },
    { id: 367, question: "¿La potencia de un punto es la misma para cualquier secante desde ese punto?", options: ["Sí, siempre es la misma", "No, depende de la secante", "Solo para secantes paralelas", "Solo si el punto es exterior"], correctIndex: 0, explanation: "El producto PA × PB es constante para todas las secantes trazadas desde un mismo punto.", difficulty: "basico" },
    { id: 368, question: "Si la distancia al centro es d = 5 y el radio es r = 3, ¿cuál es la potencia?", options: ["16", "8", "2", "25"], correctIndex: 0, explanation: "Potencia = d² − r² = 25 − 9 = 16.", difficulty: "basico" },
    { id: 369, question: "Si d = 5 y r = 3, ¿el punto es interior o exterior?", options: ["Exterior, porque d > r", "Interior, porque d < r", "Sobre la circunferencia", "En el centro"], correctIndex: 0, explanation: "Como d = 5 > r = 3, el punto está fuera de la circunferencia.", difficulty: "basico" },
    { id: 370, question: "Si PT = 4 y PA × PB = 16, ¿es correcta la relación de potencia?", options: ["Sí, porque PT² = PA × PB", "No, no están relacionadas", "Solo si P es interior", "Solo si la secante es un diámetro"], correctIndex: 0, explanation: "PT² = 16 = PA × PB. La relación de potencia se verifica.", difficulty: "intermedio" },
    { id: 371, question: "Si PA = 3 y PB = 12, ¿cuánto mide la tangente desde P?", options: ["6", "4", "3", "9"], correctIndex: 0, explanation: "PT² = 3 × 12 = 36. PT = 6.", difficulty: "intermedio" },
    { id: 372, question: "¿Qué valor tiene la potencia de un punto interior a la circunferencia?", options: ["Es negativa", "Es positiva", "Es cero", "Depende del radio"], correctIndex: 0, explanation: "Si el punto está dentro, d < r, entonces d² − r² < 0.", difficulty: "intermedio" },
    { id: 373, question: "Si PC × PD = 20 y PC = 5, ¿cuánto miden PD y PT?", options: ["PD = 4, PT = 2√5", "PD = 4, PT = 20", "PD = 5, PT = 5", "PD = 10, PT = 10"], correctIndex: 0, explanation: "PD = 20 / 5 = 4. PT² = 20, PT = 2√5.", difficulty: "intermedio" },
    { id: 374, question: "Si la potencia de un punto es −9, ¿qué tipo de punto es?", options: ["Interior a la circunferencia", "Exterior a la circunferencia", "Sobre la circunferencia", "En el centro"], correctIndex: 0, explanation: "Una potencia negativa indica que el punto está dentro de la circunferencia.", difficulty: "intermedio" },
    { id: 375, question: "¿Cómo se calcula la potencia conociendo las coordenadas del punto, del centro y el radio?", options: ["(x−h)² + (y−k)² − r²", "x² + y² − r²", "(x + h)² − r²", "r² − (x + y)²"], correctIndex: 0, explanation: "La potencia es PO² − r² = (x−h)² + (y−k)² − r².", difficulty: "intermedio" },
    { id: 376, question: "Si PT = 5, ¿cuánto vale PA × PB para cualquier secante desde P?", options: ["25", "10", "5", "50"], correctIndex: 0, explanation: "PA × PB = PT² = 25 para toda secante desde P.", difficulty: "intermedio" },
    { id: 377, question: "Si dos cuerdas AB y CD se cortan en P dentro de la circunferencia, ¿qué relación se cumple?", options: ["PA × PB = PC × PD", "PA + PB = PC + PD", "PA / PB = PC / PD", "PA − PB = PC − PD"], correctIndex: 0, explanation: "El teorema de potencia para punto interior establece PA × PB = PC × PD.", difficulty: "avanzado" },
    { id: 378, question: "¿Qué es la recta radical de dos circunferencias?", options: ["El lugar de puntos con igual potencia respecto a ambas", "La recta que une sus centros", "La tangente común", "La perpendicular a la línea de centros"], correctIndex: 0, explanation: "La recta radical es el conjunto de puntos con la misma potencia respecto a las dos circunferencias.", difficulty: "avanzado" },
    { id: 379, question: "Si dos circunferencias tienen centros en (0,0) y (5,0) con radios 3 y 4, ¿cuál es la potencia de (0,0) respecto a la segunda?", options: ["9", "25", "7", "16"], correctIndex: 0, explanation: "Distancia entre centros = 5. Potencia = 5² − 4² = 25 − 16 = 9.", difficulty: "avanzado" },
    { id: 380, question: "Si PT = 4√3, ¿cuál es la potencia de P respecto a la circunferencia?", options: ["48", "12", "4√3", "24"], correctIndex: 0, explanation: "La potencia es PT² = (4√3)² = 48.", difficulty: "avanzado" },
    { id: 381, question: "Si PA × PB = 36, ¿cuánto mide la tangente PT desde el mismo punto exterior P?", options: ["6", "36", "18", "12"], correctIndex: 0, explanation: "PT² = PA × PB = 36. PT = 6.", difficulty: "avanzado" },
    { id: 382, question: "Si desde un punto exterior P se trazan dos secantes PAB y PCD, con PA = 2, PB = 8, PC = 4, ¿cuánto mide PD?", options: ["4", "8", "2", "16"], correctIndex: 0, explanation: "PA × PB = PC × PD → 2 × 8 = 4 × PD → PD = 4.", difficulty: "avanzado" },
    { id: 383, question: "Si un punto tiene potencia 0 respecto a una circunferencia, ¿dónde está ubicado?", options: ["Exactamente sobre la circunferencia", "Dentro de la circunferencia", "Fuera de la circunferencia", "En el centro"], correctIndex: 0, explanation: "Potencia = 0 significa que el punto está sobre la circunferencia.", difficulty: "avanzado" }
  ]
