    { id: 528, question: "En un triángulo, si A = 30°, a = 10 y B = 45°, ¿cuál es b?", options: ["10√2", "10√3", "5√2", "20"], correctIndex: 0, explanation: "b = a·sen(B)/sen(A) = 10·sen(45°)/sen(30°) = 10·(√2/2)/(1/2) = 10√2.", difficulty: "basic" },
    { id: 529, question: "La Ley de Senos relaciona:", options: ["Lados con sus ángulos opuestos", "Lados adyacentes a un ángulo", "Solo ángulos entre sí", "Solo lados entre sí"], correctIndex: 0, explanation: "La Ley de Senos relaciona cada lado con el seno de su ángulo opuesto.", difficulty: "basic" },
    { id: 530, question: "Si en un triángulo a = 8, A = 60° y B = 30°, ¿cuál es b?", options: ["4√3", "8√3", "8", "16"], correctIndex: 0, explanation: "b = a·sen(B)/sen(A) = 8·sen(30°)/sen(60°) = 8·(1/2)/(√3/2) = 8/√3 = 4√3.", difficulty: "basic" },
    { id: 531, question: "¿Qué representa el valor 2R en la Ley de Senos?", options: ["El diámetro de la circunferencia circunscrita", "El radio de la circunferencia inscrita", "El área del triángulo", "La suma de los lados"], correctIndex: 0, explanation: "2R es el diámetro de la circunferencia circunscrita al triángulo.", difficulty: "basic" },
    { id: 532, question: "Si a/sen(A) = b/sen(B), ¿qué podemos encontrar?", options: ["Un lado si conocemos el otro lado y dos ángulos", "Solo ángulos", "Solo lados", "El área del triángulo"], correctIndex: 0, explanation: "La Ley de Senos permite encontrar un lado desconocido si conocemos otro lado y dos ángulos.", difficulty: "basic" },
    { id: 533, question: "En un triángulo, A = 45°, B = 60° y a = 10. ¿Cuál es b?", options: ["10√6/3", "10√2", "10√3", "20√2/3"], correctIndex: 0, explanation: "b = a·sen(B)/sen(A) = 10·sen(60°)/sen(45°) = 10·(√3/2)/(√2/2) = 10√3/√2 = 10√6/3.", difficulty: "intermediate" },
    { id: 534, question: "En un triángulo, a = 12, b = 8 y A = 60°. ¿Cuál es B?", options: ["arcsen(2√3/3)", "arcsen(1/2)", "arcsen(√3/2)", "arcsen(1/3)"], correctIndex: 0, explanation: "sen(B) = b·sen(A)/a = 8·sen(60°)/12 = 8·(√3/2)/12 = 4√3/12 = √3/3. B = arcsen(√3/3).", difficulty: "intermediate" },
    { id: 535, question: "Un triángulo tiene lados a = 7, b = 10 y ángulo A = 30°. ¿Cuántos triángulos posibles existen?", options: ["2 triángulos", "1 triángulo", "0 triángulos", "Infinitos triángulos"], correctIndex: 0, explanation: "Este es el caso ambiguo SSA. Como b·sen(A) < a < b, existen 2 soluciones posibles.", difficulty: "intermediate" },
    { id: 536, question: "En un triángulo, A = 120°, a = 20 y b = 10. ¿Cuál es c?", options: ["10√3", "20", "10", "10√2"], correctIndex: 0, explanation: "Primero hallamos B usando la Ley de Senos, luego C = 180° - A - B, y finalmente c.", difficulty: "intermediate" },
    { id: 537, question: "La circunferencia circunscrita a un triángulo con a = 6, A = 30° tiene radio:", options: ["6", "3", "12", "3√3"], correctIndex: 0, explanation: "2R = a/sen(A) = 6/sen(30°) = 6/(1/2) = 12 → R = 6.", difficulty: "intermediate" },
    { id: 538, question: "En un triángulo, b = 15, C = 45° y B = 60°. ¿Cuál es c?", options: ["15√2/√3", "15√3", "15√2", "30/√3"], correctIndex: 0, explanation: "c = b·sen(C)/sen(B) = 15·sen(45°)/sen(60°) = 15·(√2/2)/(√3/2) = 15√2/√3.", difficulty: "intermediate" },
    { id: 539, question: "En un triángulo, a = 8, b = 6 y C = 60°. Usando la Ley de Senos y la de Cosenos, ¿cuál es c?", options: ["2√13", "7", "2√7", "√52"], correctIndex: 0, explanation: "Primero usamos la Ley de Cosenos: c² = a² + b² - 2ab·cos(C) = 64 + 36 - 96·cos(60°) = 100 - 48 = 52.", difficulty: "advanced" },
    { id: 540, question: "En un triángulo, a = 5, b = 7 y c = 8. ¿Cuál es el radio de la circunferencia circunscrita?", options: ["7√3/3", "7", "14/√3", "8"], correctIndex: 0, explanation: "Primero calculamos el área con la fórmula de Herón, luego R = abc/(4Δ).", difficulty: "advanced" },
    { id: 541, question: "Un barco observa dos faros con ángulos de 30° y 45°. Si la distancia entre faros es 10 km, ¿cuál es la distancia del barco al faro más cercano?", options: ["10·sen(30°)/sen(105°)", "10·sen(45°)/sen(105°)", "10·sen(105°)/sen(30°)", "10/sen(105°)"], correctIndex: 0, explanation: "Usando la Ley de Senos en el triángulo formado por el barco y los dos faros.", difficulty: "advanced" },
    { id: 542, question: "¿Cuál es el área de un triángulo con a = 10, A = 30° y B = 45°?", options: ["25√2/3", "25√3", "50/3", "25"], correctIndex: 0, explanation: "Primero hallamos C = 105°, luego b = a·sen(B)/sen(A), y área = (1/2)ab·sen(C).", difficulty: "advanced" },
    { id: 543, question: "En un triángulo esférico, ¿qué versión de la Ley de Senos se utiliza?", options: ["sen(a)/sen(A) = sen(b)/sen(B) = sen(c)/sen(C)", "a/sen(A) = b/sen(B) = c/sen(C)", "cos(a)/sen(A) = cos(b)/sen(B)", "sen(a)/cos(A) = sen(b)/cos(B)"], correctIndex: 0, explanation: "En trigonometría esférica, la Ley de Senos usa senos de los lados (arcos).", difficulty: "advanced" },
    { id: 544, question: "Si en un triángulo a = 2b, ¿qué relación existe entre A y B?", options: ["sen(A) = 2sen(B)", "A = 2B", "cos(A) = 2cos(B)", "tan(A) = 2tan(B)"], correctIndex: 0, explanation: "Por la Ley de Senos: a/sen(A) = b/sen(B) → 2b/sen(A) = b/sen(B) → sen(A) = 2sen(B).", difficulty: "advanced" },
    { id: 545, question: "En un triángulo, si a/sen(A) = b/sen(B) = c/sen(C) = 10, ¿cuál es el diámetro de la circunferencia circunscrita?", options: ["10", "5", "20", "10π"], correctIndex: 0, explanation: "El valor común es 2R, por lo tanto 2R = 10 y el diámetro es 10.", difficulty: "advanced" },
    { id: 546, question: "¿Cuál es la relación entre la Ley de Senos y el teorema de los senos en un triángulo?", options: ["Son equivalentes", "La Ley de Senos es una generalización", "Son completamente distintos", "La Ley de Senos solo funciona para triángulos rectángulos"], correctIndex: 0, explanation: "La Ley de Senos es una generalización del teorema de los senos para cualquier triángulo.", difficulty: "advanced" }
