    { id: 663, question: "¿Qué es un lugar geométrico?", options: ["Un punto fijo en el plano", "El conjunto de puntos que cumplen una condición dada", "Una curva cerrada", "Un segmento de recta"], correctIndex: 1, explanation: "Un lugar geométrico es el conjunto de todos los puntos que satisfacen una condición específica.", difficulty: "basic" },
    { id: 664, question: "¿Cuál es el lugar geométrico de los puntos equidistantes de un punto fijo?", options: ["Una recta", "Una circunferencia", "Una elipse", "Un segmento"], correctIndex: 1, explanation: "Los puntos a distancia constante de un punto forman una circunferencia.", difficulty: "basic" },
    { id: 665, question: "¿Cuál es el lugar geométrico de los puntos equidistantes de dos puntos fijos A y B?", options: ["La recta perpendicular al segmento AB por su punto medio", "La mediatriz del segmento AB", "La circunferencia de diámetro AB", "La bisectriz del ángulo formado"], correctIndex: 1, explanation: "Los puntos equidistantes de A y B forman la mediatriz del segmento AB.", difficulty: "basic" },
    { id: 666, question: "¿Cuál es el lugar geométrico de los puntos que están a la misma distancia de dos rectas paralelas?", options: ["Una recta paralela a ambas y equidistante", "Una circunferencia", "Dos rectas", "Un punto"], correctIndex: 0, explanation: "Los puntos equidistantes de dos rectas paralelas forman una recta paralela intermedia.", difficulty: "basic" },
    { id: 667, question: "¿Qué lugar geométrico se forma con los puntos cuya suma de distancias a dos fijos es constante?", options: ["Hipérbola", "Elipse", "Parábola", "Circunferencia"], correctIndex: 1, explanation: "Si la suma de distancias a dos focos es constante (mayor que la distancia entre ellos), es una elipse.", difficulty: "basic" },
    { id: 668, question: "¿Qué lugar geométrico describen los puntos cuya distancia a un foco es igual a su distancia a una directriz?", options: ["Elipse", "Hipérbola", "Parábola", "Circunferencia"], correctIndex: 2, explanation: "La parábola se define como el lugar de puntos equidistantes de un foco y una directriz.", difficulty: "basic" },
    { id: 669, question: "¿Qué lugar geométrico es el conjunto de puntos medios de cuerdas paralelas de una circunferencia?", options: ["Un diámetro", "Una recta perpendicular a las cuerdas por el centro", "Otra circunferencia", "Un punto"], correctIndex: 1, explanation: "Los puntos medios de cuerdas paralelas están sobre un diámetro perpendicular a dichas cuerdas.", difficulty: "basic" },
    { id: 670, question: "¿Cuál es el lugar geométrico de los puntos que están a distancia 3 del punto (1, 2)?", options: ["(x-1)² + (y-2)² = 9", "(x-1)² + (y-2)² = 3", "(x+1)² + (y+2)² = 9", "x² + y² = 9"], correctIndex: 0, explanation: "Circunferencia con centro (1,2) y radio 3: (x-1)²+(y-2)²=9.", difficulty: "intermediate" },
    { id: 671, question: "¿Cuál es el lugar geométrico de los puntos que dividen internamente un segmento AB en razón 2:1?", options: ["Un punto (el baricentro)", "Una recta", "Un segmento", "Una circunferencia"], correctIndex: 0, explanation: "Un punto que divide un segmento en una razón fija es un punto único.", difficulty: "intermediate" },
    { id: 672, question: "¿Qué lugar geométrico describen los vértices de todos los rectángulos inscritos en una circunferencia?", options: ["La misma circunferencia", "Un círculo menor", "Una elipse", "Un cuadrado"], correctIndex: 0, explanation: "Los vértices de cualquier rectángulo inscrito en una circunferencia están sobre ella.", difficulty: "intermediate" },
    { id: 673, question: "¿Cuál es el lugar geométrico de los puntos cuya distancia al eje x es el doble que su distancia al eje y?", options: ["y = ±2x", "y = ±x/2", "x = ±2y", "y = 2x²"], correctIndex: 0, explanation: "|y| = 2|x| → y = ±2x, que son dos rectas que pasan por el origen.", difficulty: "intermediate" },
    { id: 674, question: "¿Qué lugar geométrico forman los puntos de tangencia de las rectas trazadas desde un punto exterior a una circunferencia?", options: ["Una recta (polar del punto)", "Una circunferencia", "Una elipse", "Dos puntos"], correctIndex: 0, explanation: "Los puntos de tangencia desde un punto exterior a una circunferencia están sobre la recta polar de dicho punto.", difficulty: "intermediate" },
    { id: 675, question: "Si A = (0, 0) y B = (4, 0), ¿cuál es el lugar geométrico de los puntos P tales que ∠APB = 90°?", options: ["La circunferencia de diámetro AB (excepto A y B)", "La recta x = 2", "El segmento AB", "La semicircunferencia superior"], correctIndex: 0, explanation: "Los puntos que forman ángulo recto con un segmento están sobre la circunferencia de diámetro ese segmento.", difficulty: "intermediate" },
    { id: 676, question: "¿Cuál es el lugar geométrico de los puntos cuya distancia al punto (0, 0) es igual a su distancia a la recta x = 4?", options: ["Una parábola", "Una elipse", "Una circunferencia", "Una hipérbola"], correctIndex: 0, explanation: "Es la definición de parábola: foco en (0,0), directriz x=4. Ecuación: x²+y² = (x-4)² → y² = -8x+16.", difficulty: "advanced" },
    { id: 677, question: "¿Qué lugar geométrico describen los puntos de intersección de rectas perpendiculares que pasan por los extremos de un diámetro de una circunferencia?", options: ["La misma circunferencia", "Una elipse", "Dos rectas", "El centro"], correctIndex: 0, explanation: "Por el teorema de Thales, los puntos de intersección de rectas perpendiculares que pasan por extremos de un diámetro están sobre la circunferencia.", difficulty: "advanced" },
    { id: 678, question: "¿Cuál es el lugar geométrico de los centros de las circunferencias tangentes internamente a dos circunferencias dadas?", options: ["Una elipse", "Una hipérbola", "Una parábola", "Una recta"], correctIndex: 0, explanation: "Los centros de circunferencias tangentes internamente a dos circunferencias forman una elipse.", difficulty: "advanced" },
    { id: 679, question: "Si A=(-3, 0) y B=(3, 0), ¿cuál es el lugar geométrico de los puntos P tales que PA/PB = 2?", options: ["Una circunferencia (Círculo de Apolonio)", "Una elipse", "Una hipérbola", "Una recta"], correctIndex: 0, explanation: "El lugar de puntos cuya razón de distancias a dos puntos fijos es constante (≠1) es una circunferencia, llamada Círculo de Apolonio.", difficulty: "advanced" }
