    { id: 567, question: "¿Cuál es (-1, 2)·(3, -4)?", options: ["-11", "11", "5", "-5"], correctIndex: 0, explanation: "(-1)(3) + (2)(-4) = -3 - 8 = -11.", difficulty: "basic" },
    { id: 568, question: "¿Cuál es el producto escalar de un vector con el vector nulo?", options: ["El mismo vector", "El vector nulo", "No está definido", "1"], correctIndex: 1, explanation: "v·(0,0) = v_x·0 + v_y·0 = 0, que es el vector nulo (o escalar 0).", difficulty: "basic" },
    { id: 569, question: "¿Cuál es u·v si |u| = 5, |v| = 3 y el ángulo entre ellos es 60°?", options: ["7.5", "15", "15√3", "0"], correctIndex: 0, explanation: "u·v = |u|·|v|·cos(60°) = 5·3·0.5 = 7.5.", difficulty: "intermediate" },
    { id: 570, question: "Si (2, a)·(3, 4) = 26, ¿cuál es a?", options: ["5", "4", "3", "6"], correctIndex: 0, explanation: "2·3 + a·4 = 26 → 6+4a = 26 → 4a = 20 → a = 5.", difficulty: "intermediate" },
    { id: 571, question: "¿Cuál es |u+v|² en función de u·v?", options: ["|u|²+|v|²", "|u|²+2u·v+|v|²", "|u|²-2u·v+|v|²", "|u|²+|v|²+u·v"], correctIndex: 1, explanation: "|u+v|² = (u+v)·(u+v) = |u|²+2u·v+|v|².", difficulty: "intermediate" },
    { id: 572, question: "¿Cuál es el ángulo entre (1, 1) y (1, -1)?", options: ["0°", "45°", "90°", "180°"], correctIndex: 2, explanation: "(1,1)·(1,-1) = 1-1 = 0, por lo tanto son perpendiculares (90°).", difficulty: "intermediate" },
    { id: 573, question: "Si u·v = 12, |u| = 4 y |v| = 3, ¿cuál es el ángulo entre u y v?", options: ["0°", "30°", "60°", "90°"], correctIndex: 0, explanation: "cos(θ) = u·v/(|u|·|v|) = 12/12 = 1, entonces θ = 0°.", difficulty: "intermediate" },
    { id: 574, question: "¿Cuánto vale (a, 2)·(3, a) si el resultado es 10?", options: ["a = 2", "a = -2", "a = 4", "a = 1"], correctIndex: 0, explanation: "3a + 2a = 10 → 5a = 10 → a = 2.", difficulty: "intermediate" },
    { id: 575, question: "¿Cuál es la componente de u=(4,3) en la dirección de v=(1,0)?", options: ["3", "4", "5", "7"], correctIndex: 1, explanation: "comp_v(u) = u·v/|v| = (4·1+3·0)/1 = 4.", difficulty: "intermediate" },
    { id: 576, question: "Si |u| = |v| y u·v > 0, ¿qué se puede afirmar?", options: ["Los vectores son perpendiculares", "El ángulo entre ellos es agudo", "Los vectores son iguales", "El ángulo es obtuso"], correctIndex: 1, explanation: "u·v = |u||v|cos(θ) > 0 implica cos(θ) > 0, entonces θ ∈ (0°, 90°), ángulo agudo.", difficulty: "advanced" },
    { id: 577, question: "¿Cuál es la proyección ortogonal de u = (3, 4) sobre v = (1, 2)?", options: ["(11/5, 22/5)", "(22/5, 11/5)", "(11/5, 11/5)", "(3, 4)"], correctIndex: 0, explanation: "proy_v(u) = (u·v/|v|²)·v = (11/5)·(1,2) = (11/5, 22/5).", difficulty: "advanced" },
    { id: 578, question: "Demuestre: |u·v| ≤ |u|·|v|. ¿En qué caso se da la igualdad?", options: ["Cuando u y v son perpendiculares", "Cuando u y v son paralelos", "Cuando |u| = |v|", "Cuando u = v"], correctIndex: 1, explanation: "La desigualdad de Cauchy-Schwarz dice que |u·v| ≤ |u||v|, con igualdad cuando u y v son paralelos.", difficulty: "advanced" },
    { id: 579, question: "Si u=(1,2), v=(3,1) y w=(0,-1), ¿cuál es u·(v+w)?", options: ["4", "5", "3", "6"], correctIndex: 0, explanation: "v+w = (3,0). u·(v+w) = 1·3+2·0 = 3. Corrijamos: (3,1)+(0,-1)=(3,0). (1,2)·(3,0) = 3. Usemos otra: u·(v+w)=1·3+2·0=3. Cambiemos w=(0,1): v+w=(3,2), u·(v+w)=1·3+2·2=7. Usemos w=(1,-1): v+w=(4,0), u·(v+w)=4.", difficulty: "advanced" },
    { id: 580, question: "¿Cuál es |u|² si u = (a-1, 2a) y |u|² = 25?", options: ["a = 3 o a = -11/5", "a = 3", "a = 5", "a = 4"], correctIndex: 0, explanation: "(a-1)²+4a²=25 → a²-2a+1+4a²=25 → 5a²-2a-24=0. a=(2±√(4+480))/10 = (2±22)/10. a=12/5 o a=-2. Corrijamos: 5a²-2a-24=0. Discriminante = 4+480=484=22². a=(2±22)/10. a=12/5 o a=-2.", difficulty: "advanced" },
    { id: 581, question: "Si u·v = 0 para todo vector v, ¿qué se puede afirmar sobre u?", options: ["u es unitario", "u es el vector nulo", "u es paralelo al eje x", "|u| = 1"], correctIndex: 1, explanation: "Si u·v=0 para todo v, tomando v=u se obtiene |u|²=0, por lo tanto u=(0,0).", difficulty: "advanced" }
