    { id: 641, question: "¿Qué figura se obtiene al cortar un cono con un plano paralelo a su base?", options: ["Elipse", "Círculo", "Parábola", "Hipérbola"], correctIndex: 1, explanation: "Un corte paralelo a la base de un cono produce siempre un círculo, ya que la sección es similar a la base.", difficulty: "basico" },
    { id: 642, question: "¿Qué sección cónica se forma cuando un plano corta un cono paralelamente a su generatriz?", options: ["Círculo", "Elipse", "Parábola", "Hipérbola"], correctIndex: 2, explanation: "Cuando el plano es paralelo a una generatriz del cono, la sección es una parábola.", difficulty: "basico" },
    { id: 643, question: "¿Qué figura resulta al cortar un cilindro con un plano paralelo a su eje?", options: ["Elipse", "Círculo", "Rectángulo", "Parábola"], correctIndex: 2, explanation: "Un corte paralelo al eje de un cilindro produce un rectángulo.", difficulty: "basico" },
    { id: 644, question: "¿Qué sección se forma al cortar una esfera con cualquier plano?", options: ["Elipse", "Círculo", "Parábola", "Rectángulo"], correctIndex: 1, explanation: "Cualquier plano que corte una esfera produce siempre una circunferencia (círculo en 2D).", difficulty: "basico" },
    { id: 645, question: "Un cono tiene radio 6 cm y altura 8 cm. Un plano paralelo a la base corta el cono a 3 cm del vértice. ¿Cuál es el radio de la sección?", options: ["2.25 cm", "3 cm", "4 cm", "4.5 cm"], correctIndex: 0, explanation: "Por semejanza: r/6 = 3/8, r = 18/8 = 2.25 cm.", difficulty: "basico" },
    { id: 646, question: "¿Qué cónica se forma cuando un plano corta ambos conos de un doble cono y es perpendicular al eje?", options: ["Elipse", "Parábola", "Hipérbola", "Círculo"], correctIndex: 2, explanation: "Un plano perpendicular al eje que corta ambos conos produce una hipérbola.", difficulty: "basico" },
    { id: 647, question: "¿Qué sección cónica tiene dos focos?", options: ["Círculo", "Parábola", "Elipse", "Todas las anteriores"], correctIndex: 2, explanation: "La elipse es la única cónica con dos focos. La parábola tiene uno y la hipérbola tiene dos pero en conos separados.", difficulty: "basico" },
    { id: 648, question: "Un prisma hexagonal regular tiene arista de base 5 cm y altura 12 cm. ¿Cuál es el área de la sección transversal?", options: ["25√3/2 cm²", "75√3/2 cm²", "150√3 cm²", "25√3 cm²"], correctIndex: 0, explanation: "La sección transversal de un prisma regular es su base: hexágono regular de lado 5. A = (3√3/2)(25) = 75√3/2 cm².", difficulty: "intermedio" },
    { id: 649, question: "Un cilindro de radio 4 cm y altura 10 cm es cortado por un plano que forma un ángulo de 45° con el eje. ¿Cuál es la forma de la sección?", options: ["Círculo", "Elipse", "Rectángulo", "Parábola"], correctIndex: 1, explanation: "Un plano que corta un cilindro en ángulo (no paralelo ni perpendicular al eje) produce una elipse.", difficulty: "intermedio" },
    { id: 650, question: "Un cubo de arista 8 cm es cortado por un plano que pasa por los puntos medios de tres aristas que comparten un vértice. ¿Cuál es el área de la sección?", options: ["8√3 cm²", "16√3 cm²", "32 cm²", "24 cm²"], correctIndex: 0, explanation: "La sección es un triángulo equilátero con lado 4√2. A = (√3/4)(32) = 8√3 cm².", difficulty: "intermedio" },
    { id: 651, question: "Un cono de radio 5 cm y altura 12 cm es cortado por un plano paralelo a la base a 4 cm de la base. ¿Cuál es el área de la sección?", options: ["25π/9 cm²", "100π/9 cm²", "400π/9 cm²", "25π cm²"], correctIndex: 1, explanation: "El plano está a 12 - 4 = 8 cm del vértice. r/5 = 8/12, r = 10/3. A = π(10/3)² = 100π/9 cm².", difficulty: "intermedio" },
    { id: 652, question: "Un triángulo rectángulo con catetos 6 y 8 gira alrededor de la hipotenusa. ¿Qué sección transversal perpendicular al eje se obtiene?", options: ["Círculo", "Elipse", "Dos círculos concéntricos", "Anillo"], correctIndex: 1, explanation: "Al girar alrededor de la hipotenusa se genera un doble cono. Un corte perpendicular al eje produce un círculo, pero la sección oblicua produce una elipse.", difficulty: "intermedio" },
    { id: 653, question: "¿Cuál es la relación entre el área de la base y el área de una sección paralela a 1/3 de la altura del vértice en un cono?", options: ["1:3", "1:9", "1:27", "1:6"], correctIndex: 1, explanation: "Por semejanza, la relación de áreas es el cuadrado de la relación de distancias: (1/3)² = 1/9.", difficulty: "intermedio" },
    { id: 654, question: "Un cubo de arista 6 cm es cortado por un plano diagonal que pasa por dos aristas opuestas paralelas. ¿Cuál es el área de la sección?", options: ["18 cm²", "36 cm²", "36√2 cm²", "18√2 cm²"], correctIndex: 1, explanation: "La sección es un rectángulo de lados 6 y 6√2. A = 6 × 6√2 = 36√2 cm².", difficulty: "intermedio" },
    { id: 655, question: "Un cono de radio 3 cm y altura 4 cm es cortado por un plano paralelo a una generatriz. ¿Qué tipo de sección se forma?", options: ["Círculo", "Elipse", "Parábola", "Hipérbola"], correctIndex: 2, explanation: "Un plano paralelo a una generatriz del cono produce una parábola.", difficulty: "avanzado" },
    { id: 656, question: "Un cilindro de radio 5 cm y altura 12 cm es cortado por un plano oblicuo que genera una elipse. Si el eje mayor de la elipse mide 13 cm, ¿cuánto mide el eje menor?", options: ["5 cm", "8 cm", "10 cm", "12 cm"], correctIndex: 2, explanation: "El eje menor de la elipse es igual al diámetro del cilindro: 2r = 10 cm. El eje mayor depende del ángulo de inclinación del plano.", difficulty: "avanzado" },
    { id: 657, question: "Una esfera de radio 5 cm es cortada por dos planos paralelos a distancias 3 cm y 4 cm del centro (en el mismo lado). ¿Cuál es la altura de la zona resultante?", options: ["1 cm", "3 cm", "4 cm", "7 cm"], correctIndex: 0, explanation: "La altura de la zona entre los planos es la diferencia de las distancias: |4 - 3| = 1 cm.", difficulty: "avanzado" },
    { id: 658, question: "Un cono tiene una sección elíptica cuando es cortado por un plano. Si los semiejes de la elipse son 4 cm y 5 cm, ¿cuál es el área de la elipse?", options: ["10π cm²", "20π cm²", "25π cm²", "40π cm²"], correctIndex: 1, explanation: "A = πab = π(4)(5) = 20π cm².", difficulty: "avanzado" },
    { id: 659, question: "Un cubo de arista a es cortado por un plano que pasa por los puntos medios de 6 aristas, formando un hexágono regular. ¿Cuál es el área del hexágono?", options: ["a²√3/2", "a²√3/4", "3a²√3/4", "a²√3"], correctIndex: 0, explanation: "El lado del hexágono es a√2/2. A = (3√3/2)(a√2/2)² = (3√3/2)(a²/2) = 3a²√3/4. Corrigiendo: A = (3√3/2) · a²/2 = 3a²√3/4.", difficulty: "avanzado" },
    { id: 660, question: "Un prisma triangular recto tiene una sección oblicua. Si la sección transversal perpendicular tiene un área de 20 cm² y el plano de corte forma un ángulo de 60° con el eje, ¿cuál es el área de la sección oblicua?", options: ["20√3 cm²", "40/√3 cm²", "40 cm²", "20/√3 cm²"], correctIndex: 1, explanation: "A_oblicua = A_perpendicular / sen θ = 20/sen 60° = 20/(√3/2) = 40/√3 cm².", difficulty: "avanzado" }
