    { id: 700, question: "¿Qué es el baricentro de un triángulo?", options: ["El punto de intersección de las tres mediatrices", "El punto de intersección de las tres medianas", "El punto de intersección de las tres alturas", "El punto de intersección de las tres bisectrices"], correctIndex: 1, explanation: "El baricentro G es el punto de intersección de las tres medianas del triángulo. Divide cada mediana en razón 2:1 desde el vértice.", difficulty: "basico" },
    { id: 701, question: "¿Cuántos centros notables tiene un triángulo?", options: ["2", "3", "4", "5"], correctIndex: 2, explanation: "Un triángulo tiene cuatro centros notables: baricentro (G), circuncentro (O), ortocentro (H) e incentro (I).", difficulty: "basico" },
    { id: 702, question: "¿Qué es el circuncentro de un triángulo?", options: ["El punto de intersección de las medianas", "El punto de intersección de las mediatrices", "El punto de intersección de las alturas", "El centro del círculo inscrito"], correctIndex: 1, explanation: "El circuncentro O es el punto de intersección de las mediatrices de los tres lados del triángulo.", difficulty: "basico" },
    { id: 703, question: "¿Qué relación describe la recta de Euler entre el ortocentro H, el baricentro G y el circuncentro O?", options: ["HG = GO", "HG = 2·GO", "HO = 2·HG", "G divide a HO en partes iguales"], correctIndex: 1, explanation: "La recta de Euler establece que H, G y O están alineados y HG = 2·GO, con G entre H y O.", difficulty: "basico" },
    { id: 704, question: "Si el baricentro de un triángulo es G(4, 5), ¿qué propiedad cumple respecto a los vértices?", options: ["G es el punto medio de todos los lados", "G = (A + B + C)/3", "G está sobre todos los lados", "G equidista de los tres vértices"], correctIndex: 1, explanation: "El baricentro tiene coordenadas G = (A + B + C)/3, es decir, es el promedio aritmético de las coordenadas de los vértices.", difficulty: "basico" },
    { id: 705, question: "El incentro de un triángulo es:", options: ["El punto más cercano a los vértices", "El punto de intersección de las medianas", "El punto de intersección de las bisectrices internas", "El punto medio de la hipotenusa"], correctIndex: 2, explanation: "El incentro I es el punto de intersección de las tres bisectrices internas del triángulo y es el centro del círculo inscrito.", difficulty: "basico" },
    { id: 706, question: "¿Qué sucede con los centros notables en un triángulo equilátero?", options: ["Solo coinciden dos centros", "Solo coinciden tres centros", "Los cuatro centros coinciden en un solo punto", "Ningún centro coincide"], correctIndex: 2, explanation: "En un triángulo equilátero, los cuatro centros notables (H, G, O, I) coinciden en un solo punto, el centro del triángulo.", difficulty: "intermedio" },
    { id: 707, question: "Si el ortocentro es H(2, 8) y el circuncentro es O(8, 2), ¿cuáles son las coordenadas del baricentro G?", options: ["(6, 4)", "(5, 5)", "(4, 6)", "(3, 7)"], correctIndex: 0, explanation: "G divide a HO en razón HG:GO = 2:1 desde H. Usando división de segmento: G = H + (2/3)(O - H) = (2 + 4, 8 - 4) = (6, 4).", difficulty: "intermedio" },
    { id: 708, question: "¿Cuál es el centro de la circunferencia de los nueve puntos en relación con la recta de Euler?", options: ["Es el punto medio de HG", "Es el punto medio de OH", "No está sobre la recta de Euler", "Es el mismo punto que el baricentro"], correctIndex: 1, explanation: "El centro de la circunferencia de los nueve puntos N es el punto medio de OH y está sobre la recta de Euler, entre G y O.", difficulty: "intermedio" },
    { id: 709, question: "En un triángulo rectángulo, ¿dónde se ubica el circuncentro?", options: ["En el vértice del ángulo recto", "En el punto medio de la hipotenusa", "Fuera del triángulo", "En el baricentro"], correctIndex: 1, explanation: "En un triángulo rectángulo, el circuncentro es el punto medio de la hipotenusa, ya que la mediatriz de la hipotenusa pasa por ese punto.", difficulty: "intermedio" },
    { id: 710, question: "Si G divide a HN en razón 2:1 y N es el punto medio de OH, ¿cuál es la relación entre HG y GN?", options: ["HG = GN", "HG = 2·GN", "GN = 2·HG", "HG = 3·GN"], correctIndex: 1, explanation: "G divide a HN en razón 2:1, por lo tanto HG = 2·GN. Esto se verifica porque HG = 2·GO y GN = GO.", difficulty: "intermedio" },
    { id: 711, question: "La recta de Euler coincide con una mediana solo cuando el triángulo es:", options: ["Equilátero", "Isósceles", "Escaleno", "Rectángulo"], correctIndex: 1, explanation: "En un triángulo isósceles, la mediana que biseca el ángulo entre los lados iguales también contiene a H, G y O, por lo que la recta de Euler coincide con esa mediana.", difficulty: "intermedio" },
    { id: 712, question: "¿Qué representa la distancia OH en un triángulo no equilátero?", options: ["Siempre es igual al circunradio", "Se calcula como OH² = 9R² - (a² + b² + c²)", "Es siempre mayor que el radio de la circunferencia inscrita", "No se puede determinar sin conocer las coordenadas"], correctIndex: 1, explanation: "La fórmula de Euler establece que OH² = 9R² - (a² + b² + c²), donde R es el circunradio y a, b, c son los lados del triángulo.", difficulty: "avanzado" },
    { id: 713, question: "Si los vértices de un triángulo en el plano complejo son z₁ = 0, z₂ = 6 y z₂ = 3 + 3i, ¿cuáles son las coordenadas del baricentro?", options: ["(3, 1)", "(1, 1)", "(2, 2)", "(3, 3)"], correctIndex: 0, explanation: "G = (A + B + C)/3 = ((0 + 6 + 3)/3, (0 + 0 + 3)/3) = (9/3, 3/3) = (3, 1).", difficulty: "avanzado" },
    { id: 714, question: "¿En qué cuántos puntos se intersecan las tres mediatrices de un triángulo?", options: ["Siempre en 3 puntos distintos", "Siempre en 1 punto", "Depende del tipo de triángulo", "Las mediatrices nunca se cortan"], correctIndex: 1, explanation: "Las tres mediatrices de cualquier triángulo siempre concurren en un punto único: el circuncentro O.", difficulty: "basico" },
    { id: 715, question: "Si H = (1, 7) y O = (7, 1), ¿cuáles son las coordenadas del centro N de la circunferencia de los nueve puntos?", options: ["(4, 4)", "(3, 3)", "(5, 5)", "(6, 6)"], correctIndex: 0, explanation: "N es el punto medio de OH: N = ((1+7)/2, (7+1)/2) = (8/2, 8/2) = (4, 4).", difficulty: "intermedio" },
    { id: 716, question: "Un triángulo tiene lados a = 5, b = 6, c = 7. ¿Cuál es el producto a² + b² + c²?", options: ["50", "86", "110", "120"], correctIndex: 2, explanation: "a² + b² + c² = 25 + 36 + 49 = 110. Este valor se usa en la fórmula de Euler: OH² = 9R² - 110.", difficulty: "basico" },
    { id: 717, question: "Si el baricentro es G(3, 4), el circuncentro es O(6, 7) y el ortocentro es H(x, y), ¿cuáles son las coordenadas de H?", options: ["(0, 1)", "(-3, -2)", "(9, 10)", "(12, 14)"], correctIndex: 0, explanation: "De HG = 2·GO, con GO = G - O = (3-6, 4-7) = (-3, -3), entonces HG = 2·(-3, -3) = (-6, -6). Así H = G - HG = (3-(-6), 4-(-6))... Usando G = (H+2O)/3: H = 3G - 2O = (9-12, 12-14) = (-3, -2). La respuesta correcta es (-3, -2).", difficulty: "avanzado" },
    { id: 718, question: "¿Qué relación existe entre el baricentro y las medianas de un triángulo?", options: ["El baricentro divide cada mediana en partes iguales", "El baricentro está sobre cada mediana y la divide en razón 2:1 desde el vértice", "El baricentro no pertenece a las medianas", "El baricentro divide cada mediana en razón 1:2 desde el vértice"], correctIndex: 1, explanation: "El baricentro está sobre cada mediana y la divide en razón 2:1 contando desde el vértice hacia el lado opuesto.", difficulty: "intermedio" },
    { id: 719, question: "Si un triángulo tiene vértices en A(0,0), B(6,0) y C(3,6), ¿cuál es la coordenada y del baricentro?", options: ["1", "2", "3", "4"], correctIndex: 1, explanation: "G_y = (0 + 0 + 6)/3 = 6/3 = 2. La coordenada y del baricentro es el promedio de las coordenadas y de los vértices.", difficulty: "basico" },
    { id: 720, question: "¿Cuál es la distancia entre el baricentro G y el circuncentro O si HG = 12?", options: ["4", "6", "8", "12"], correctIndex: 1, explanation: "Por la relación de Euler, HG = 2·GO. Si HG = 12, entonces GO = 12/2 = 6.", difficulty: "intermedio" }
