    { id: 401, question: "Si A = {1, 2, 3}, cuantos elementos tiene A?", options: ["2", "3", "4", "6"], correctIndex: 1, explanation: "El conjunto A tiene exactamente 3 elementos: 1, 2 y 3.", difficulty: "basico" },
    { id: 402, question: "Que simbolo se utiliza para indicar que un elemento pertenece a un conjunto?", options: ["subset", "elemento de", "union", "interseccion"], correctIndex: 1, explanation: "El simbolo de pertenencia indica que un elemento esta en un conjunto.", difficulty: "basico" },
    { id: 403, question: "Si A = {a, b, c} y B = {b, c, d}, cual es A interseccion B?", options: ["{a, b, c, d}", "{b, c}", "{a, d}", "{a, b, c}"], correctIndex: 1, explanation: "La interseccion contiene los elementos que estan en ambos conjuntos: b y c.", difficulty: "basico" },
    { id: 404, question: "Que significa A subset B?", options: ["A es igual a B", "A es subconjunto de B", "A es superconjunto de B", "A y B son disjuntos"], correctIndex: 1, explanation: "A subset B significa que todos los elementos de A estan en B.", difficulty: "basico" },
    { id: 405, question: "Si A = {1, 2} y B = {3, 4}, cual es A union B?", options: ["{1, 2, 3, 4}", "{1, 2}", "{3, 4}", "vacio"], correctIndex: 0, explanation: "La union contiene todos los elementos de A junto con todos los de B.", difficulty: "basico" },
    { id: 406, question: "Que conjunto se llama complemento de A respecto a U?", options: ["Los elementos de A que no estan en U", "Los elementos de U que no estan en A", "Los elementos comunes a A y U", "Todos los elementos de A y U"], correctIndex: 1, explanation: "El complemento contiene los elementos del conjunto universal que no estan en A.", difficulty: "basico" },
    { id: 407, question: "Si U = {1,2,3,4,5,6} y A = {2,4,6}, cual es el complemento de A?", options: ["{1,3,5}", "{2,4,6}", "{1,2,3,4,5,6}", "vacio"], correctIndex: 0, explanation: "El complemento contiene los elementos de U que no estan en A: {1, 3, 5}.", difficulty: "intermedio" },
    { id: 408, question: "Cuantos subconjuntos tiene un conjunto con 4 elementos?", options: ["4", "8", "16", "32"], correctIndex: 2, explanation: "Un conjunto con n elementos tiene 2^n subconjuntos. Para n=4: 2^4 = 16.", difficulty: "intermedio" },
    { id: 409, question: "Si A = pares entre 1 y 10 y B = multiplos de 3 entre 1 y 10, cual es A interseccion B?", options: ["{6}", "{2,4,6,8,10}", "{3,6,9}", "{6,12}"], correctIndex: 0, explanation: "Los pares son {2,4,6,8,10} y los multiplos de 3 son {3,6,9}. Interseccion: {6}.", difficulty: "intermedio" },
    { id: 410, question: "Que ley establece que A union (B interseccion C) = (A union B) interseccion (A union C)?", options: ["Ley conmutativa", "Ley asociativa", "Ley distributiva", "Ley de De Morgan"], correctIndex: 2, explanation: "La ley distributiva de la union sobre la interseccion establece esta igualdad.", difficulty: "intermedio" },
    { id: 411, question: "Si n(A) = 15, n(B) = 10 y n(A interseccion B) = 3, cual es n(A union B)?", options: ["18", "22", "25", "28"], correctIndex: 1, explanation: "Por inclusion-exclusion: n(A union B) = 15 + 10 - 3 = 22.", difficulty: "intermedio" },
    { id: 412, question: "Cual es la diferencia simetrica de A = {1,2,3} y B = {2,3,4}?", options: ["{1,4}", "{2,3}", "{1,2,3,4}", "vacio"], correctIndex: 0, explanation: "La diferencia simetrica contiene los elementos que estan en A o en B pero no en ambos: {1, 4}.", difficulty: "intermedio" },
    { id: 413, question: "Si A subset B y B subset C, que se puede concluir?", options: ["C subset A", "A subset C", "A = C", "B = C"], correctIndex: 1, explanation: "La relacion de subconjunto es transitiva: si A subset B y B subset C, entonces A subset C.", difficulty: "intermedio" },
    { id: 414, question: "Si A = {1,2,3,4,5}, cuantos subconjuntos propios tiene A?", options: ["31", "32", "30", "25"], correctIndex: 0, explanation: "Un conjunto con n elementos tiene 2^n - 1 subconjuntos propios. Para n=5: 31.", difficulty: "avanzado" },
    { id: 415, question: "Cual es la relacion de De Morgan para el complemento de (A interseccion B)?", options: ["A' union B'", "A' interseccion B'", "A union B", "A' union B"], correctIndex: 0, explanation: "La ley de De Morgan establece que (A interseccion B)' = A' union B'.", difficulty: "avanzado" },
    { id: 416, question: "Si n(U) = 50, n(A) = 20, n(B) = 25 y n(A interseccion B) = 8, cuantos elementos no estan ni en A ni en B?", options: ["3", "8", "13", "20"], correctIndex: 2, explanation: "n(A union B) = 20 + 25 - 8 = 37. Fuera de ambos: 50 - 37 = 13.", difficulty: "avanzado" },
    { id: 417, question: "Que tipo de conjunto es el conjunto de los numeros racionales respecto a los reales?", options: ["Conjunto disjunto", "Subconjunto propio", "Conjunto igual", "Conjunto vacio"], correctIndex: 1, explanation: "Los racionales son subconjunto propio de los reales, ya que existen irracionales.", difficulty: "avanzado" },
    { id: 418, question: "Si A producto cartesiano B = {(1,x),(1,y),(2,x),(2,y)}, cuales son A y B?", options: ["A={1,2}, B={x,y}", "A={x,y}, B={1,2}", "A={1,x}, B={2,y}", "A={(1,2)}, B={(x,y)}"], correctIndex: 0, explanation: "El producto cartesiano contiene todos los pares (a,b) con a en A y b en B.", difficulty: "avanzado" },
    { id: 419, question: "Si A = {1,2,3} y B = {2,3,4,5}, cual es la diferencia A menos B?", options: ["{1}", "{4,5}", "{1,4,5}", "{2,3}"], correctIndex: 0, explanation: "A menos B contiene los elementos de A que no estan en B: solo el 1.", difficulty: "avanzado" },
    { id: 420, question: "Cuantos elementos tiene A producto cartesiano B si n(A) = 5 y n(B) = 4?", options: ["9", "20", "1", "45"], correctIndex: 1, explanation: "n(A x B) = n(A) * n(B) = 5 * 4 = 20.", difficulty: "avanzado" }
  ,
    { id: 400, question: "Que representa el conjunto vacio?", options: ["Un conjunto sin elementos", "Un conjunto con un elemento", "Un conjunto infinito", "Un conjunto con todos los numeros"], correctIndex: 0, explanation: "El conjunto vacio es aquel que no contiene ningun elemento.", difficulty: "basico" },
    { id: 401, question: "Si A = {1, 2, 3}, cuantos elementos tiene A?", options: ["2", "3", "4", "6"], correctIndex: 1, explanation: "El conjunto A tiene exactamente 3 elementos: 1, 2 y 3.", difficulty: "basico" },
    { id: 402, question: "Que simbolo se utiliza para indicar que un elemento pertenece a un conjunto?", options: ["subset", "elemento de", "union", "interseccion"], correctIndex: 1, explanation: "El simbolo de pertenencia indica que un elemento esta en un conjunto.", difficulty: "basico" },
    { id: 403, question: "Si A = {a, b, c} y B = {b, c, d}, cual es A interseccion B?", options: ["{a, b, c, d}", "{b, c}", "{a, d}", "{a, b, c}"], correctIndex: 1, explanation: "La interseccion contiene los elementos que estan en ambos conjuntos: b y c.", difficulty: "basico" },
    { id: 404, question: "Que significa A subset B?", options: ["A es igual a B", "A es subconjunto de B", "A es superconjunto de B", "A y B son disjuntos"], correctIndex: 1, explanation: "A subset B significa que todos los elementos de A estan en B.", difficulty: "basico" },
    { id: 405, question: "Si A = {1, 2} y B = {3, 4}, cual es A union B?", options: ["{1, 2, 3, 4}", "{1, 2}", "{3, 4}", "vacio"], correctIndex: 0, explanation: "La union contiene todos los elementos de A junto con todos los de B.", difficulty: "basico" },
    { id: 406, question: "Que conjunto se llama complemento de A respecto a U?", options: ["Los elementos de A que no estan en U", "Los elementos de U que no estan en A", "Los elementos comunes a A y U", "Todos los elementos de A y U"], correctIndex: 1, explanation: "El complemento contiene los elementos del conjunto universal que no estan en A.", difficulty: "basico" },
    { id: 407, question: "Si U = {1,2,3,4,5,6} y A = {2,4,6}, cual es el complemento de A?", options: ["{1,3,5}", "{2,4,6}", "{1,2,3,4,5,6}", "vacio"], correctIndex: 0, explanation: "El complemento contiene los elementos de U que no estan en A: {1, 3, 5}.", difficulty: "intermedio" },
    { id: 408, question: "Cuantos subconjuntos tiene un conjunto con 4 elementos?", options: ["4", "8", "16", "32"], correctIndex: 2, explanation: "Un conjunto con n elementos tiene 2^n subconjuntos. Para n=4: 2^4 = 16.", difficulty: "intermedio" },
    { id: 409, question: "Si A = pares entre 1 y 10 y B = multiplos de 3 entre 1 y 10, cual es A interseccion B?", options: ["{6}", "{2,4,6,8,10}", "{3,6,9}", "{6,12}"], correctIndex: 0, explanation: "Los pares son {2,4,6,8,10} y los multiplos de 3 son {3,6,9}. Interseccion: {6}.", difficulty: "intermedio" },
    { id: 410, question: "Que ley establece que A union (B interseccion C) = (A union B) interseccion (A union C)?", options: ["Ley conmutativa", "Ley asociativa", "Ley distributiva", "Ley de De Morgan"], correctIndex: 2, explanation: "La ley distributiva de la union sobre la interseccion establece esta igualdad.", difficulty: "intermedio" },
    { id: 411, question: "Si n(A) = 15, n(B) = 10 y n(A interseccion B) = 3, cual es n(A union B)?", options: ["18", "22", "25", "28"], correctIndex: 1, explanation: "Por inclusion-exclusion: n(A union B) = 15 + 10 - 3 = 22.", difficulty: "intermedio" },
    { id: 412, question: "Cual es la diferencia simetrica de A = {1,2,3} y B = {2,3,4}?", options: ["{1,4}", "{2,3}", "{1,2,3,4}", "vacio"], correctIndex: 0, explanation: "La diferencia simetrica contiene los elementos que estan en A o en B pero no en ambos: {1, 4}.", difficulty: "intermedio" },
    { id: 413, question: "Si A subset B y B subset C, que se puede concluir?", options: ["C subset A", "A subset C", "A = C", "B = C"], correctIndex: 1, explanation: "La relacion de subconjunto es transitiva: si A subset B y B subset C, entonces A subset C.", difficulty: "intermedio" },
    { id: 414, question: "Si A = {1,2,3,4,5}, cuantos subconjuntos propios tiene A?", options: ["31", "32", "30", "25"], correctIndex: 0, explanation: "Un conjunto con n elementos tiene 2^n - 1 subconjuntos propios. Para n=5: 31.", difficulty: "avanzado" },
    { id: 415, question: "Cual es la relacion de De Morgan para el complemento de (A interseccion B)?", options: ["A' union B'", "A' interseccion B'", "A union B", "A' union B"], correctIndex: 0, explanation: "La ley de De Morgan establece que (A interseccion B)' = A' union B'.", difficulty: "avanzado" },
    { id: 416, question: "Si n(U) = 50, n(A) = 20, n(B) = 25 y n(A interseccion B) = 8, cuantos elementos no estan ni en A ni en B?", options: ["3", "8", "13", "20"], correctIndex: 2, explanation: "n(A union B) = 20 + 25 - 8 = 37. Fuera de ambos: 50 - 37 = 13.", difficulty: "avanzado" },
    { id: 417, question: "Que tipo de conjunto es el conjunto de los numeros racionales respecto a los reales?", options: ["Conjunto disjunto", "Subconjunto propio", "Conjunto igual", "Conjunto vacio"], correctIndex: 1, explanation: "Los racionales son subconjunto propio de los reales, ya que existen irracionales.", difficulty: "avanzado" },
    { id: 418, question: "Si A producto cartesiano B = {(1,x),(1,y),(2,x),(2,y)}, cuales son A y B?", options: ["A={1,2}, B={x,y}", "A={x,y}, B={1,2}", "A={1,x}, B={2,y}", "A={(1,2)}, B={(x,y)}"], correctIndex: 0, explanation: "El producto cartesiano contiene todos los pares (a,b) con a en A y b en B.", difficulty: "avanzado" },
    { id: 419, question: "Si A = {1,2,3} y B = {2,3,4,5}, cual es la diferencia A menos B?", options: ["{1}", "{4,5}", "{1,4,5}", "{2,3}"], correctIndex: 0, explanation: "A menos B contiene los elementos de A que no estan en B: solo el 1.", difficulty: "avanzado" },
    { id: 420, question: "Cuantos elementos tiene A producto cartesiano B si n(A) = 5 y n(B) = 4?", options: ["9", "20", "1", "45"], correctIndex: 1, explanation: "n(A x B) = n(A) * n(B) = 5 * 4 = 20.", difficulty: "avanzado" }
