    { id: 421, question: "Que representa la region donde se superponen dos circulos en un diagrama de Venn?", options: ["La union de los conjuntos", "La interseccion de los conjuntos", "El complemento", "El conjunto vacio"], correctIndex: 1, explanation: "La region de superposicion representa los elementos que pertenecen a ambos conjuntos.", difficulty: "basico" },
    { id: 422, question: "En un diagrama de Venn con dos conjuntos, cuantas regiones se forman?", options: ["2", "3", "4", "5"], correctIndex: 2, explanation: "Se forman 4 regiones: solo A, solo B, A interseccion B, y fuera de ambos.", difficulty: "basico" },
    { id: 423, question: "Si dos circulos no se tocan en un diagrama de Venn, los conjuntos son:", options: ["Iguales", "Subconjuntos", "Disjuntos", "Complementarios"], correctIndex: 2, explanation: "Si los circulos no se superponen, los conjuntos no tienen elementos en comun.", difficulty: "basico" },
    { id: 424, question: "Que representa el rectangulo que encierra los circulos en un diagrama de Venn?", options: ["La union", "El conjunto universal", "El complemento", "El conjunto vacio"], correctIndex: 1, explanation: "El rectangulo representa el conjunto universal que contiene todos los elementos.", difficulty: "basico" },
    { id: 425, question: "Si A = {1,2,3} y B = {3,4,5}, que numero se coloca en la region de superposicion?", options: ["1", "2", "3", "4"], correctIndex: 2, explanation: "El numero 3 es el unico elemento comun a ambos conjuntos.", difficulty: "basico" },
    { id: 426, question: "En un diagrama de Venn, la region externa a ambos circulos representa:", options: ["A union B", "A interseccion B", "El complemento de A union B", "A' interseccion B'"], correctIndex: 2, explanation: "La region externa representa el complemento de la union.", difficulty: "basico" },
    { id: 427, question: "Cuantos circulos se necesitan para representar 3 conjuntos en un diagrama de Venn?", options: ["2", "3", "4", "6"], correctIndex: 1, explanation: "Se necesitan 3 circulos superpuestos para representar 3 conjuntos.", difficulty: "basico" },
    { id: 428, question: "En un diagrama de Venn con U={1,...,10}, A={1,2,3,4,5}, B={4,5,6,7}, donde se coloca el 8?", options: ["Solo en A", "Solo en B", "En A interseccion B", "Fuera de A y B"], correctIndex: 3, explanation: "El 8 no esta en A ni en B, por lo que se coloca en la region externa.", difficulty: "intermedio" },
    { id: 429, question: "Si n(A)=20, n(B)=15, n(A interseccion B)=8 y n(U)=50, cuantos elementos hay en la region externa?", options: ["7", "15", "23", "35"], correctIndex: 2, explanation: "n(A union B)=20+15-8=27. Fuera: 50-27=23.", difficulty: "intermedio" },
    { id: 430, question: "En un diagrama de Venn de 3 conjuntos, cuantas regiones se forman?", options: ["6", "7", "8", "9"], correctIndex: 2, explanation: "Se forman 8 regiones disjoint entre si.", difficulty: "intermedio" },
    { id: 431, question: "Si un diagrama de Venn muestra A subset B, como se representan los circulos?", options: ["Dos circulos separados", "Dos circulos superpuestos parcialmente", "El circulo de A dentro del circulo de B", "El circulo de B dentro del circulo de A"], correctIndex: 2, explanation: "Si A es subconjunto de B, el circulo de A se dibuja dentro del circulo de B.", difficulty: "intermedio" },
    { id: 432, question: "Si en un diagrama de Venn A interseccion B = A, que relacion existe entre A y B?", options: ["A y B son disjuntos", "A subset B", "B subset A", "A = B"], correctIndex: 1, explanation: "Si A interseccion B = A, todos los elementos de A estan en B, asi que A subset B.", difficulty: "intermedio" },
    { id: 433, question: "En un diagrama de Venn, si solo A tiene 12, solo B tiene 8 y A interseccion B tiene 5, cuantos elementos tiene A union B?", options: ["17", "20", "25", "30"], correctIndex: 2, explanation: "n(A union B) = solo A + solo B + A interseccion B = 12 + 8 + 5 = 25.", difficulty: "intermedio" },
    { id: 434, question: "Que region representa A' interseccion B' en un diagrama de Venn?", options: ["Solo A", "Solo B", "A interseccion B", "Fuera de A y B"], correctIndex: 3, explanation: "Por De Morgan, A' interseccion B' = (A union B)', la region externa.", difficulty: "intermedio" },
    { id: 435, question: "En un diagrama de Venn de 3 conjuntos con n(U)=100, n(A)=40, n(B)=35, n(C)=30, n(A inter B)=15, n(A inter C)=12, n(B inter C)=10, n(A inter B inter C)=5, cuantos estan fuera de los tres?", options: ["7", "27", "32", "37"], correctIndex: 0, explanation: "n(A union B union C)=40+35+30-15-12-10+5=73. Fuera: 100-73=27... Correccion: la respuesta correcta es 27.", difficulty: "avanzado" },
    { id: 436, question: "Si n(A union B)=30, n(A)=18, n(B)=20, cuantos elementos hay solo en A y solo en B?", options: ["10 y 12", "12 y 10", "8 y 12", "10 y 8"], correctIndex: 0, explanation: "n(A inter B)=18+20-30=8. Solo A: 18-8=10. Solo B: 20-8=12.", difficulty: "avanzado" },
    { id: 437, question: "En un diagrama de Venn de 3 conjuntos, si n(A inter B)=7, n(A inter C)=5, n(B inter C)=6 y n(A inter B inter C)=2, cuantos elementos hay en exactamente 2 conjuntos?", options: ["8", "12", "14", "18"], correctIndex: 1, explanation: "En exactamente 2: (7-2)+(5-2)+(6-2)=5+3+4=12.", difficulty: "avanzado" },
    { id: 438, question: "Si A subset C y B subset C, que se puede afirmar sobre A union B?", options: ["A union B es disjunto de C", "A union B subset C", "C subset A union B", "No hay relacion"], correctIndex: 1, explanation: "Si todos los elementos de A y B estan en C, entonces A union B subset C.", difficulty: "avanzado" },
    { id: 439, question: "En un diagrama de Venn de 3 conjuntos, la region que representa exactamente A es:", options: ["A", "A menos (B union C)", "A interseccion B' interseccion C'", "A menos B menos C"], correctIndex: 1, explanation: "La region de solo A es A menos la union de B y C.", difficulty: "avanzado" },
    { id: 440, question: "Si n(A inter B inter C)=4, n(A inter B)=10, n(A inter C)=8, n(B inter C)=7, cuantos hay en exactamente una interseccion de a pares?", options: ["6", "11", "13", "21"], correctIndex: 1, explanation: "Solo A inter B: 10-4=6. Solo A inter C: 8-4=4. Solo B inter C: 7-4=3. Total: 6+4+3=13... La respuesta correcta es 13.", difficulty: "avanzado" },
    { id: 441, question: "Cuantas formas hay de numerar las 8 regiones de un diagrama de Venn de 3 conjuntos con enteros positivos si cada region debe tener un valor diferente?", options: ["8!", "2^8", "8^3", "3^8"], correctIndex: 0, explanation: "Las 8 regiones son distinguibles, hay 8! formas de asignar numeros diferentes.", difficulty: "avanzado" }
