    { id: 104, question: "Si 12 obreros hacen un muro en 10 días, ¿cuántos obreros para 5 días?", options: ["18", "20", "24", "30"], correctIndex: 2, explanation: "12×10=120 obreros-día. 120÷5=24 obreros.", difficulty: "basic" },
    { id: 105, question: "Si 6 tanques llenan en 4 horas, ¿cuántos llenan en 2 horas?", options: ["6", "8", "10", "12"], correctIndex: 3, explanation: "6×4=24 tanques-hora. 24÷2=12.", difficulty: "basic" },
    { id: 106, question: "Si 100m de tubería cuestan $5000, ¿cuánto cuestan 60m?", options: ["$2500", "$3000", "$3500", "$4000"], correctIndex: 1, explanation: "100=$5000, 1=$50. 60×50=$3000.", difficulty: "basic" },
    { id: 107, question: "Si 4 máquinas producen 200 piezas en 5h, ¿cuántas producen 6 máquinas en 3h?", options: ["180", "200", "240", "360"], correctIndex: 0, explanation: "200/(4×5)=10 piezas/máquina/h. 6×3×10=180.", difficulty: "intermediate" },
    { id: 108, question: "Si un tanque se llena con 3 grifos en 8h, ¿cuánto tarda 1 grifo?", options: ["16 h", "20 h", "24 h", "32 h"], correctIndex: 2, explanation: "3×8=24 grifos-hora. 24÷1=24 horas.", difficulty: "intermediate" },
    { id: 109, question: "Si 5 excavadoras mueven 500m³ en 4h, ¿cuántas excavadoras para 750m³ en 3h?", options: ["6", "7", "8", "10"], correctIndex: 3, explanation: "500/(5×4)=25m³/máq/h. 750/(3×25)=10.", difficulty: "intermediate" },
    { id: 110, question: "Si 3 albañiles hacen una pared en 12 días, ¿cuántos días con 4 albañiles?", options: ["7", "8", "9", "10"], correctIndex: 2, explanation: "3×12=36 albañiles-día. 36÷4=9 días.", difficulty: "intermediate" },
    { id: 111, question: "Si 8 impresoras imprimen 320 páginas en 4h, ¿cuántas imprimen 480 páginas en 2h?", options: ["12", "16", "24", "32"], correctIndex: 2, explanation: "320/(8×4)=10 páginas/imp/h. 480/(2×10)=24.", difficulty: "intermediate" },
    { id: 112, question: "Si 6 empleados atienden 180 clientes en 3h, ¿cuántos empleados para 300 clientes en 5h?", options: ["4", "5", "6", "10"], correctIndex: 2, explanation: "180/(6×3)=10 clientes/emp/h. 300/(5×10)=6.", difficulty: "intermediate" },
    { id: 113, question: "Si 10 tuberías llenan un depósito en 6h, ¿cuántas tuberías para llenar el doble en 4h?", options: ["15", "20", "30", "40"], correctIndex: 2, explanation: "10×6=60. Doble depósito=120. 120÷4=30.", difficulty: "intermediate" },
    { id: 114, question: "Si A/B=3/4 y B/C=2/5, ¿cuánto vale A/C?", options: ["3/5", "3/10", "6/5", "6/20"], correctIndex: 2, explanation: "A/C=(A/B)×(B/C)=(3/4)×(2/5)=6/20=3/10.", difficulty: "advanced" },
    { id: 115, question: "Si x/y=2/3 e y/z=4/5, ¿cuánto vale x/z?", options: ["6/15", "8/15", "2/5", "10/12"], correctIndex: 1, explanation: "x/z=(2/3)×(4/5)=8/15.", difficulty: "advanced" },
    { id: 116, question: "Si 5 personas comen 10kg en 4 días, ¿cuántos comen 15kg en 6 días?", options: ["3", "4", "5", "6"], correctIndex: 2, explanation: "10/(5×4)=0.5kg/persona/día. 15/(6×0.5)=5.", difficulty: "advanced" },
    { id: 117, question: "Si 4 bombas vacían un estanque en 10h, ¿cuánto vacía 1 bomba?", options: ["20 h", "30 h", "40 h", "50 h"], correctIndex: 2, explanation: "4×10=40 bombas-hora. 40÷1=40.", difficulty: "advanced" },
    { id: 118, question: "Si a/b=5/3 y b/c=7/2, ¿cuánto vale a/c?", options: ["35/6", "12/7", "35/2", "5/6"], correctIndex: 0, explanation: "a/c=(5/3)×(7/2)=35/6.", difficulty: "advanced" },
    { id: 119, question: "Si A puede hacer un trabajo en 10h y B en 15h, ¿cuánto tardan juntos?", options: ["5 h", "6 h", "8 h", "12 h"], correctIndex: 1, explanation: "1/10+1/15=1/6. Tardan 6 horas.", difficulty: "advanced" },
    { id: 120, question: "Si 3 tanques llenan un depósito en 8h, ¿cuánto tardan 5 tanques en llenar 2 depósitos?", options: ["9.6 h", "10 h", "12 h", "16 h"], correctIndex: 0, explanation: "3×8=24. 2 depósitos=48. 48÷5=9.6 horas.", difficulty: "advanced" }
