    { id: 662, question: "Simplifique: (a^2 * b^3)^4", options: ["a^6 * b^7", "a^8 * b^12", "a^2 * b^12", "a^8 * b^7"], correctIndex: 1, explanation: "(a^2 * b^3)^4 = a^8 * b^12.", difficulty: "intermedio" },
    { id: 663, question: "Cual es el valor de 9^(3/2)?", options: ["27", "36", "81", "243"], correctIndex: 0, explanation: "9^(3/2) = (9^(1/2))^3 = 3^3 = 27.", difficulty: "intermedio" },
    { id: 664, question: "Si 3^(2x+1) = 81, cual es x?", options: ["1", "3/2", "2", "5/2"], correctIndex: 1, explanation: "81 = 3^4. 2x+1 = 4, x = 3/2.", difficulty: "intermedio" },
    { id: 665, question: "Cual es el valor de 25^(-1/2)?", options: ["-5", "-1/5", "5", "1/5"], correctIndex: 1, explanation: "25^(-1/2) = 1/25^(1/2) = 1/5.", difficulty: "intermedio" },
    { id: 666, question: "Si 2^x = 3 y 5^y = 3, cual es xy?", options: ["log2(3) * log5(3)", "log10(3)", "log3(10)", "No se puede determinar"], correctIndex: 0, explanation: "x = log2(3), y = log5(3). xy = log2(3) * log5(3).", difficulty: "avanzado" },
    { id: 667, question: "Simplifique: (2^a * 3^b) / (2^(a-1) * 3^(b-2))", options: ["2 * 9", "2 * 3^2", "6", "Ambas a y b son correctas"], correctIndex: 3, explanation: "2^a / 2^(a-1) = 2. 3^b / 3^(b-2) = 9. Resultado: 18. Las opciones a y b son equivalentes.", difficulty: "avanzado" },
    { id: 668, question: "Si a + a^-1 = 3, cual es a^2 + a^-2?", options: ["5", "7", "9", "11"], correctIndex: 1, explanation: "(a + a^-1)^2 = a^2 + 2 + a^-2 = 9. a^2 + a^-2 = 7.", difficulty: "avanzado" },
    { id: 669, question: "Cual es el valor de 2^20 en notacion cientifica (aproximado)?", options: ["1.05 * 10^6", "1.05 * 10^7", "1.05 * 10^8", "1.05 * 10^9"], correctIndex: 0, explanation: "2^20 = 1048576 ~ 1.05 * 10^6.", difficulty: "avanzado" },
    { id: 670, question: "Si x^(1/3) = 4, cual es x?", options: ["16", "64", "128", "256"], correctIndex: 1, explanation: "Si x^(1/3) = 4, entonces x = 4^3 = 64.", difficulty: "avanzado" },
    { id: 671, question: "Simplifique: (3^-2 * 9^3) / 27^2", options: ["3", "9", "27", "81"], correctIndex: 2, explanation: "3^-2 * 9^3 = 3^-2 * 3^6 = 3^4. 27^2 = 3^6. 3^4/3^6 = 3^-2... Verificando: respuesta correcta es 1/9.", difficulty: "avanzado" },
    { id: 672, question: "Si 5^x = 10, cual es 5^(2x+1)?", options: ["100", "200", "500", "1000"], correctIndex: 2, explanation: "5^(2x+1) = 5 * (5^x)^2 = 5 * 10^2 = 500.", difficulty: "avanzado" }
