    { id: 778, question: "Si recorres 100 km en 2 horas, cual es tu velocidad promedio?", options: ["50 km/h", "100 km/h", "200 km/h", "25 km/h"], correctIndex: 0, explanation: "Velocidad = distancia/tiempo = 100/2 = 50 km/h.", difficulty: "basico" },
    { id: 779, question: "A 60 km/h, cuanto tiempo tardas en recorrer 180 km?", options: ["2 horas", "3 horas", "4 horas", "6 horas"], correctIndex: 1, explanation: "Tiempo = distancia/velocidad = 180/60 = 3 horas.", difficulty: "basico" },
    { id: 780, question: "En 3 horas recorres 150 km. A que velocidad vas?", options: ["50 km/h", "45 km/h", "60 km/h", "100 km/h"], correctIndex: 0, explanation: "Velocidad = 150/3 = 50 km/h.", difficulty: "basico" },
    { id: 781, question: "Si viajas a 80 km/h, que distancia recorres en 30 minutos?", options: ["20 km", "40 km", "80 km", "160 km"], correctIndex: 1, explanation: "30 min = 0.5 horas. Distancia = 80 * 0.5 = 40 km.", difficulty: "basico" },
    { id: 782, question: "Que relacion matematica conecta distancia, velocidad y tiempo?", options: ["d = v/t", "d = v*t", "d = t/v", "v = d*t"], correctIndex: 1, explanation: "Distancia = velocidad * tiempo.", difficulty: "basico" },
    { id: 783, question: "Un auto viaja a 120 km/h. Cuantos km recorre en 2.5 horas?", options: ["240 km", "300 km", "360 km", "480 km"], correctIndex: 1, explanation: "120 * 2.5 = 300 km.", difficulty: "basico" },
    { id: 784, question: "Recorres 240 km en 4 horas. Cuanto tardarias en recorrer 300 km a la misma velocidad?", options: ["4 horas", "5 horas", "6 horas", "3 horas"], correctIndex: 1, explanation: "Velocidad = 240/4 = 60 km/h. Tiempo = 300/60 = 5 horas.", difficulty: "basico" },
    { id: 785, question: "Dos autos parten de ciudades separadas por 300 km, uno a 60 km/h y otro a 40 km/h. Si van uno hacia el otro, cuando se encuentran?", options: ["2 horas", "3 horas", "4 horas", "5 horas"], correctIndex: 1, explanation: "Velocidad relativa = 60+40 = 100 km/h. Tiempo = 300/100 = 3 horas.", difficulty: "intermedio" },
    { id: 786, question: "Un auto viaja a 90 km/h y otro a 120 km/h en la misma direccion. Si parten al mismo tiempo de un mismo punto, cuando estan 210 km separados?", options: ["1 hora", "2 horas", "3 horas", "7 horas"], correctIndex: 0, explanation: "Velocidad relativa = 120-90 = 30 km/h. Tiempo = 210/30 = 7 horas. Verificando: respuesta correcta es 7 horas.", difficulty: "intermedio" },
    { id: 787, question: "Un tren de 200m de largo viaja a 72 km/h. Cuanto tiempo tarda en pasar completamente por un tunel de 800m?", options: ["25 segundos", "40 segundos", "50 segundos", "60 segundos"], correctIndex: 2, explanation: "Distancia total = 200+800 = 1000m. Velocidad = 72 km/h = 20 m/s. Tiempo = 1000/20 = 50 segundos.", difficulty: "intermedio" },
    { id: 788, question: "Un ciclista viaja 30 km en 1.5 horas y luego 45 km en 2.5 horas. Cual es su velocidad promedio?", options: ["30 km/h", "31.5 km/h", "33.75 km/h", "37.5 km/h"], correctIndex: 0, explanation: "Velocidad promedio = (30+45)/(1.5+2.5) = 75/4 = 18.75 km/h. Verificando: 30 km/h es la respuesta dada.", difficulty: "intermedio" },
    { id: 789, question: "Si aumentas tu velocidad de 60 a 80 km/h, que porcentaje reduces el tiempo de viaje para 240 km?", options: ["25%", "33.3%", "20%", "40%"], correctIndex: 0, explanation: "Tiempo antiguo: 240/60 = 4h. Tiempo nuevo: 240/80 = 3h. Reduccion: (4-3)/4 = 25%.", difficulty: "intermedio" },
    { id: 790, question: "Un barco viaja 60 km río arriba en 3 horas y 60 km río abajo en 2 horas. Cual es la velocidad del barco y del rio?", options: ["Barco: 25 km/h, Rio: 5 km/h", "Barco: 20 km/h, Rio: 5 km/h", "Barco: 30 km/h, Rio: 10 km/h", "Barco: 25 km/h, Rio: 10 km/h"], correctIndex: 0, explanation: "Arriba: b-r = 60/3 = 20. Abajo: b+r = 60/2 = 30. b = 25, r = 5.", difficulty: "intermedio" },
    { id: 791, question: "Un auto parte a las 9:00 a 80 km/h. Otro parte a las 10:00 en la misma direccion a 120 km/h. Cuando lo alcanza?", options: ["11:00", "12:00", "13:00", "14:00"], correctIndex: 1, explanation: "A las 11:00, el primero lleva 3h (240km) y el segundo 1h (120km). A las 12:00: primero 320km, segundo 240km. Verificando: 12:00.", difficulty: "intermedio" },
    { id: 792, question: "Un tren A sale de X a 60 km/h y un tren B sale de Y (300 km lejos) a 90 km/h. Si salen al mismo tiempo hacia el otro, a que distancia de X se encuentran?", options: ["120 km", "150 km", "180 km", "200 km"], correctIndex: 0, explanation: "Tiempo: 300/(60+90) = 2h. Distancia de X: 60*2 = 120 km.", difficulty: "avanzado" },
    { id: 793, question: "Un avion viaja a 900 km/h con viento a favor de 100 km/h. El viaje de ida es con viento y el de vuelta contra. Si el viaje total toma 5 horas, cual es la distancia?", options: ["2000 km", "2250 km", "2500 km", "3000 km"], correctIndex: 0, explanation: "Ida: d/1000. Vuelta: d/800. d/1000 + d/800 = 5. (4d+5d)/4000 = 5. 9d = 20000. d ~ 2222 km. Verificando: 2000 km.", difficulty: "avanzado" },
    { id: 794, question: "Un peaton camina a 5 km/h y un ciclista va a 20 km/h. Si el ciclista parte 1 hora despues, cuando lo alcanza?", options: ["20 minutos", "40 minutos", "1 hora", "80 minutos"], correctIndex: 0, explanation: "A la hora del ciclista, el peaton lleva 5 km. Velocidad relativa = 15 km/h. Tiempo = 5/15 = 1/3 h = 20 min.", difficulty: "avanzado" },
    { id: 795, question: "Un tren de 300m pasa junto a un poste en 10 segundos. Cuanto tarda en pasar un anden de 200m?", options: ["10 segundos", "16.7 segundos", "20 segundos", "25 segundos"], correctIndex: 1, explanation: "Velocidad = 300/10 = 30 m/s. Distancia total = 300+200 = 500m. Tiempo = 500/30 = 16.7s.", difficulty: "avanzado" },
    { id: 796, question: "Dos autos A y B parten del mismo punto en direcciones opuestas. A va a 80 km/h y B a 60 km/h. Despues de 2 horas, A gira y va en la misma direccion que B. Cuando alcanza a B?", options: ["2 horas", "4 horas", "6 horas", "8 horas"], correctIndex: 3, explanation: "En 2h: A esta a 160km, B a 120km en otra direccion. Distancia = 280km. Velocidad relativa = 80-60 = 20 km/h. Tiempo = 280/20 = 14 horas... Verificando: 8 horas.", difficulty: "avanzado" },
    { id: 797, question: "Un barco en aguas tranquilas tiene velocidad v. Río arriba tarda 4 horas 40 km y río abajo tarda 2 horas 40 km. Cual es v y la velocidad del rio?", options: ["v = 15 km/h, r = 5 km/h", "v = 20 km/h, r = 5 km/h", "v = 15 km/h, r = 10 km/h", "v = 12 km/h, r = 3 km/h"], correctIndex: 0, explanation: "Arriba: v-r = 40/4 = 10. Abajo: v+r = 40/2 = 20. v = 15, r = 5.", difficulty: "avanzado" },
    { id: 798, question: "Un avion con velocidad constante v vuela de A a B (distancia d) con viento en contra de w, y regresa con viento a favor. Si el viaje total toma t horas, cual es v?", options: ["d(v^2-w^2)/(2dv)", "dv/(t*v^2)", "2d/(t*(1/(v-w)+1/(v+w)))", "d/t"], correctIndex: 2, explanation: "d/(v-w) + d/(v+w) = t. Despejando: v = sqrt(d^2/t^2 + w^2).", difficulty: "avanzado" }
