    { id: 851, question: "Si el area de un circulo es directamente proporcional al radio al cuadrado, y el radio se triplica, que pasa con el area?", options: ["Se triplica", "Se nonuplica", "Se duplica", "Se sextuplica"], correctIndex: 1, explanation: "Si el radio se triplica, el area se multiplica por 3^2 = 9.", difficulty: "intermedio" },
    { id: 852, question: "Si y es directamente proporcional a x y inversamente proporcional a z, y cuando x=4, z=2, y=10, cual es la constante?", options: ["5", "10", "20", "40"], correctIndex: 0, explanation: "y = kx/z. 10 = k*4/2. 10 = 2k. k = 5.", difficulty: "intermedio" },
    { id: 853, question: "Si 3 agentes venden $9000 en 5 dias, cuanto venden 7 agentes en 10 dias?", options: ["$21000", "$35000", "$42000", "$28000"], correctIndex: 2, explanation: "Tasa: 9000/(3*5) = 600 por agente-dia. 7*10*600 = 42000.", difficulty: "intermedio" },
    { id: 854, question: "Si el peso de un cable es directamente proporcional a su longitud y al cuadrado de su diametro, un cable de 100m y 2cm pesa 5kg. Cuanto pesa uno de 150m y 3cm?", options: ["16.875 kg", "15 kg", "11.25 kg", "22.5 kg"], correctIndex: 0, explanation: "W = k*L*d^2. 5 = k*100*4. k = 0.0125. W = 0.0125*150*9 = 16.875 kg.", difficulty: "intermedio" },
    { id: 855, question: "Si y varia conjuntamente con x y z, y cuando x=2, z=3, y=12, cual es y cuando x=4 y z=5?", options: ["30", "40", "45", "60"], correctIndex: 1, explanation: "y = kxz. 12 = k*2*3. k = 2. y = 2*4*5 = 40.", difficulty: "avanzado" },
    { id: 856, question: "Si un tanque se vacia en T horas con n tuberias, y T es inversamente proporcional a n, con 4 tuberias se vacia en 6 horas. Con 6 tuberias, cuanto tarda?", options: ["3 horas", "4 horas", "4.5 horas", "9 horas"], correctIndex: 1, explanation: "T = k/n. 6 = k/4. k = 24. Con 6: T = 24/6 = 4 horas.", difficulty: "avanzado" },
    { id: 857, question: "Si el volumen de un gas es directamente proporcional a la temperatura y inversamente a la presion, y V=10L cuando T=300K y P=2atm, cual es V cuando T=450K y P=3atm?", options: ["10L", "15L", "20L", "7.5L"], correctIndex: 0, explanation: "V = kT/P. 10 = k*300/2. k = 1/15. V = (1/15)*450/3 = 10L.", difficulty: "avanzado" },
    { id: 858, question: "Si A es directamente proporcional a B e inversamente a C, y A=8 cuando B=4, C=2. Cual es A cuando B=6 y C=3?", options: ["6", "8", "10", "12"], correctIndex: 1, explanation: "A = kB/C. 8 = k*4/2. k = 4. A = 4*6/3 = 8.", difficulty: "avanzado" },
    { id: 859, question: "Si el peso es proporcional al volumen, y un bloque de 10cm^3 pesa 25g, que volumen tiene un bloque de 100g?", options: ["25 cm^3", "30 cm^3", "40 cm^3", "50 cm^3"], correctIndex: 2, explanation: "Densidad = 25/10 = 2.5 g/cm^3. Volumen = 100/2.5 = 40 cm^3.", difficulty: "avanzado" },
    { id: 860, question: "Si el numero de vibraciones de una cuerda es directamente proporcional a la tension al cuadrado, y al duplicar la tension las vibraciones se cuadriplican, esto es correcto?", options: ["Si, siempre", "Depende de la cuerda", "No, es incorrecto", "Solo para cuerdas metalicas"], correctIndex: 0, explanation: "Si n prop T^2, al duplicar T: n prop (2T)^2 = 4T^2. Se cuadriplican.", difficulty: "avanzado" },
    { id: 861, question: "Si y = k*x^n, y cuando x=2, y=24 y cuando x=4, y=192, cuales son k y n?", options: ["k=3, n=3", "k=6, n=2", "k=12, n=1", "k=4, n=3"], correctIndex: 0, explanation: "24 = k*2^n. 192 = k*4^n. Dividiendo: 8 = 2^n. n = 3. k = 24/8 = 3.", difficulty: "avanzado" }
