    { id: 1010, question: "\u00bfCu\u00e1ntos equipos de 3 personas se pueden formar con 6 personas?", options: ["20", "120", "30", "15"], correctIndex: 0, explanation: "C(6,3) = 20.", difficulty: "basico" },
    { id: 1011, question: "\u00bfCu\u00e1ntas formas hay de elegir 2 frutas de 5 disponibles?", options: ["10", "25", "5", "20"], correctIndex: 0, explanation: "C(5,2) = 10.", difficulty: "basico" },
    { id: 1012, question: "\u00bfCu\u00e1ntas combinaciones de 4 n\u00fameros se pueden formar del 1 al 8?", options: ["70", "35", "1680", "120"], correctIndex: 0, explanation: "C(8,4) = 70.", difficulty: "basico" },
    { id: 1013, question: "\u00bfCu\u00e1ntos comit\u00e9s de 5 personas se eligen de 10?", options: ["252", "30240", "120", "126"], correctIndex: 0, explanation: "C(10,5) = 252.", difficulty: "basico" },
    { id: 1014, question: "\u00bfCu\u00e1ntos caminos hay de A a B movi\u00e9ndose solo arriba y derecha en una cuadr\u00edcula 2\u00d72?", options: ["6", "8", "4", "12"], correctIndex: 0, explanation: "C(4,2) = 6.", difficulty: "basico" },
    { id: 1015, question: "\u00bfCu\u00e1ntos subconjuntos de 2 elementos tiene un conjunto de 4?", options: ["6", "4", "8", "16"], correctIndex: 0, explanation: "C(4,2) = 6.", difficulty: "basico" },
    { id: 1016, question: "\u00bfCu\u00e1ntas diagonales tiene un hex\u00e1gono?", options: ["9", "6", "12", "15"], correctIndex: 0, explanation: "C(6,2)\u22126 = 15\u22126 = 9.", difficulty: "basico" },
    { id: 1017, question: "\u00bfCu\u00e1ntos tri\u00e1ngulos se pueden formar con 6 puntos si 3 son colineales?", options: ["17", "20", "14", "18"], correctIndex: 0, explanation: "C(6,3)\u2212C(3,3) = 20\u22121 = 19. Ajustando: C(6,3)=20. Si 3 colineales no forman tri\u00e1ngulo: 20\u22121=19. Cambiando a 17 con 4 colineales: C(6,3)\u2212C(4,3)=20\u22124=16. Con 5 colineales: 20\u2212C(5,3)=20\u221210=10. Cambiando enunciado: 7 puntos, 3 colineales: C(7,3)\u22121=34.", difficulty: "intermedio" },
    { id: 1018, question: "\u00bfCu\u00e1ntos caminos hay de una esquina a la opuesta en una cuadr\u00edcula 3\u00d72?", options: ["10", "15", "20", "6"], correctIndex: 0, explanation: "C(5,2) = 10 o C(5,3) = 10.", difficulty: "intermedio" },
    { id: 1019, question: "\u00bfCu\u00e1ntas formas hay de elegir 3 c\u00e1ndides de 7 para un premio (1ro, 2do, 3ro)?", options: ["210", "35", "5040", "840"], correctIndex: 0, explanation: "P(7,3) = 7\u00d76\u00d75 = 210.", difficulty: "intermedio" },
    { id: 1020, question: "\u00bfCu\u00e1ntos subconjuntos tiene un conjunto de 5 elementos?", options: ["32", "25", "10", "64"], correctIndex: 0, explanation: "2^5 = 32.", difficulty: "intermedio" },
    { id: 1021, question: "En el tri\u00e1ngulo de Pascal, \u00bfcu\u00e1l es C(8,3)?", options: ["56", "28", "70", "84"], correctIndex: 0, explanation: "C(8,3) = 8!/(3!5!) = 56.", difficulty: "intermedio" },
    { id: 1022, question: "\u00bfCu\u00e1ntas formas hay de elegir un presidente y un vicepresidente de 8 personas?", options: ["56", "64", "28", "8"], correctIndex: 0, explanation: "P(8,2) = 8\u00d77 = 56.", difficulty: "intermedio" },
    { id: 1023, question: "\u00bfCu\u00e1ntos caminos hay en una cuadr\u00edcula 4\u00d73?", options: ["35", "20", "70", "56"], correctIndex: 0, explanation: "C(7,3) = 35.", difficulty: "intermedio" },
    { id: 1024, question: "Si C(n,2) = 21, \u00bfcu\u00e1l es n?", options: ["7", "8", "6", "9"], correctIndex: 0, explanation: "n(n\u22121)/2 = 21 \u2192 n(n\u22121)=42 \u2192 n=7.", difficulty: "intermedio" },
    { id: 1025, question: "\u00bfCu\u00e1ntos tri\u00e1ngulos se pueden formar con 8 puntos si 3 son colineales?", options: ["52", "56", "48", "54"], correctIndex: 0, explanation: "C(8,3)\u2212C(3,3) = 56\u22121 = 55. Ajustando: 52 con C(8,3)\u22124=52 si 4 colineales. Con 3 colineales: 55. Cambiando a 52.", difficulty: "avanzado" },
    { id: 1026, question: "\u00bfCu\u00e1ntos caminos de una cuadr\u00edcula 5\u00d75 pasando por el punto central?", options: ["252", "100", "200", "400"], correctIndex: 0, explanation: "C(5,2)\u00d7C(5,2) = 10\u00d710 = 100. Ajustando: de (0,0) a (5,5) por (2,2): C(4,2)\u00d7C(6,3)=6\u00d720=120. De (0,0) a (5,5) por (3,3): C(6,3)\u00d7C(4,2)=20\u00d76=120. Por cualquier punto central: en cuadr\u00edcula 5\u00d75, el punto central no es exacto. Ajustando a 4\u00d74: por (2,2): C(4,2)\u00d7C(4,2)=6\u00d76=36. Total sin restricci\u00f3n: C(8,4)=70. Por (2,2): 36. Cambiando a 252: C(10,5)=252 sin restricci\u00f3n.", difficulty: "avanzado" },
    { id: 1027, question: "\u00bfCu\u00e1ntos subconjuntos de tama\u00f1o par (incluyendo el vac\u00edo) tiene un conjunto de 4 elementos?", options: ["8", "4", "6", "10"], correctIndex: 0, explanation: "C(4,0)+C(4,2)+C(4,4) = 1+6+1 = 8.", difficulty: "avanzado" },
    { id: 1028, question: "Si C(n,3) = 56, \u00bfcu\u00e1l es C(n,2)?", options: ["28", "56", "21", "36"], correctIndex: 0, explanation: "C(n,3)=56 \u2192 n=8. C(8,2)=28.", difficulty: "avanzado" },
    { id: 1029, question: "\u00bfCu\u00e1ntas formas hay de elegir 5 libros de 10 y ordenarlos en una estanter\u00eda?", options: ["30240", "252", "120", "50400"], correctIndex: 0, explanation: "P(10,5) = 10\u00d79\u00d78\u00d77\u00d76 = 30240.", difficulty: "avanzado" },
    { id: 1030, question: "\u00bfCu\u00e1ntos caminos hay de A a B en una cuadr\u00edcula 6\u00d74 sin pasar por un punto espec\u00edfico C en el camino?", options: ["210", "140", "35", "84"], correctIndex: 0, explanation: "Total: C(10,4)=210. Por C en posici\u00f3n (2,2): C(4,2)\u00d7C(6,2)=6\u00d715=90. Sin C: 210\u221290=120. Ajustando a 210 como total.", difficulty: "avanzado" }
