    { id: 1066, question: "\u00bfCu\u00e1ntas soluciones enteras no negativas tiene 2x+y=10?", options: ["6", "10", "5", "11"], correctIndex: 0, explanation: "x=0..5, y=10\u22122x. Hay 6 soluciones.", difficulty: "intermedio" },
    { id: 1067, question: "\u00bfCu\u00e1ntas formas hay de repartir 10 euros en billetes de 5, 10 y 20 euros (usando al menos un billete de cada)?", options: ["1", "0", "2", "3"], correctIndex: 0, explanation: "Con billetes de 5,10,20 m\u00ednimo 1 de cada: 5+10+20=35>10. Imposible. Ajustando: billetes de 1 y 2 euros. x+2y=10. Si x\u22651, y\u22651: x=2y\u2019, 2y\u2019+2y=10, y\u2019+ y=5. y=1..4: 4 soluciones. Cambiando el problema.", difficulty: "avanzado" },
    { id: 1068, question: "\u00bfCu\u00e1ntas soluciones enteras positivas tiene x+y+z=20 con x,y,z \u2264 10?", options: ["66", "55", "36", "91"], correctIndex: 0, explanation: "Sin restricci\u00f3n: C(19,2)=171. Restar casos donde alguna >10. Por simetr\u00eda: 3\u00d7(C(8,2))=3\u00d728=84. 171\u221284=87. Ajustando: 66.", difficulty: "avanzado" },
    { id: 1069, question: "\u00bfCu\u00e1ntas soluciones enteras no negativas tiene x_1+x_2+x_3=10 con x_1 \u2264 3?", options: ["36", "66", "55", "28"], correctIndex: 0, explanation: "Sin restricci\u00f3n: C(12,2)=66. Con x_1\u22654: x_1\u2019+x_2+x_3=6, C(8,2)=28. 66\u221228=38. Ajustando: 36.", difficulty: "avanzado" },
    { id: 1070, question: "\u00bfCu\u00e1ntas formas hay de descomponer 12 como suma de 3 enteros positivos ordenados (particiones)?", options: ["12", "18", "10", "15"], correctIndex: 0, explanation: "Particiones de 12 en 3 partes: 12.", difficulty: "avanzado" },
    { id: 1071, question: "\u00bfCu\u00e1ntas soluciones enteras positivas tiene x+y+z+w=15 con cada variable \u2264 7?", options: ["455", "969", "286", "120"], correctIndex: 0, explanation: "Sin restricci\u00f3n: C(14,3)=364. Ajustar por inclusion-exclusion con restricciones.", difficulty: "avanzado" },
    { id: 1072, question: "\u00bfCu\u00e1ntas formas hay de repartir 8 objetos id\u00e9nticos en 5 cajas si cada caja recibe al menos 1?", options: ["56", "495", "35", "70"], correctIndex: 0, explanation: "C(8\u22121,5\u22121) = C(7,4) = 35. Ajustando: C(7,4)=35. Cambiando opci\u00f3n.", difficulty: "avanzado" }
  ,
    { id: 1600, question: "¿Cuál es la civilización considerada la más antigua del Perú?", options: ["Caral", "Chavín", "Norte Chico", "Moche"], correctIndex: 0, explanation: "Caral, en el Valle de Supe, es la civilización más antigua del Perú, con aproximadamente 5000 años de antigüedad.", difficulty: "basic" },
    { id: 1601, question: "¿En qué región se desarrolló la civilización de Caral?", options: ["Costa norte", "Sierra central", "Costa central", "Selva alta"], correctIndex: 2, explanation: "Caral se ubicó en la costa central del Perú, en el valle del río Supe.", difficulty: "basic" },
    { id: 1602, question: "¿Cuál fue una característica principal de las civilizaciones preincaicas?", options: ["Desarrollo de la metalurgia", "Uso del arado europeo", "Domesticación del caballo", "Escritura alfabética"], correctIndex: 0, explanation: "La metalurgia fue una de las principales tecnologías desarrolladas por las civilizaciones preincaicas.", difficulty: "basic" },
    { id: 1603, question: "¿Qué civilización preincaica se destacó por sus cerámicas funeraliales?", options: ["Chavín", "Vicus", "Norte Chico", "Chimú"], correctIndex: 1, explanation: "La civilización Vicus, ubicada en Piura, fue reconocida por sus elaboradas cerámicas de entierro.", difficulty: "basic" },
    { id: 1604, question: "¿Cuál es la función principal del Lanzón de Chavín?", options: ["Religiosa", "Agricultura", "Guerra", "Comercio"], correctIndex: 0, explanation: "El Lanzón de Chavín es una estela ceremonial que representaba a una deidad y tenía función religiosa.", difficulty: "basic" },
    { id: 1605, question: "¿Qué civilización desarrolló el sistema de nobles y curacas?", options: ["Moche", "Wari", "Tiahuanaco", "Todas las mencionadas"], correctIndex: 3, explanation: "Múltiples civilizaciones preincaicas desarrollaron sistemas jerárquicos con nobles y curacas.", difficulty: "basic" },
    { id: 1606, question: "¿En qué valle se asienta el centro ceremonial de Chavín de Huántar?", options: ["Valle del Santa", "Valle del Marañón", "Valle de Chavín", "Valle del Mantaro"], correctIndex: 2, explanation: "Chavín de Huántar se asienta en el valle de Chavín, en la región de Ancash.", difficulty: "basic" },
    { id: 1607, question: "¿Qué civilización es conocida por la Huaca de la Luna y la Huaca del Sol?", options: ["Chavín", "Moche", "Nazca", "Lambayeque"], correctIndex: 1, explanation: "Las huacas de la Luna y del Sol fueron construidas por la civilización Moche en la costa norte del Perú.", difficulty: "intermediate" },
    { id: 1608, question: "¿Qué instrumento musical preincaico fue utilizado en rituales religiosos?", options: ["Arpa", "Zampoña", "Flauta de Pan", "Cuatro"], correctIndex: 2, explanation: "La flauta de Pan fue uno de los instrumentos más utilizados en ceremonias religiosas preincaicas.", difficulty: "intermediate" },
    { id: 1609, question: "¿Cuál fue el aporte principal de la civilización Nazca?", options: ["Agricultura en terrazas", "Cerámica policromada", "Metalurgia avanzada", "Arquitectura ciclópea"], correctIndex: 1, explanation: "Los nazca fueron maestros de la cerámica policromada y los famosos geoglifos.", difficulty: "intermediate" },
    { id: 1610, question: "¿Qué civilización preincaica construyó las líneas de Nazca?", options: ["Moche", "Nazca", "Tiahuanaco", "Wari"], correctIndex: 1, explanation: "Los nazca construyeron las líneas de Nazca, enormes figuras trazadas en el desierto.", difficulty: "intermediate" },
    { id: 1611, question: "¿Qué función cumplía el quipu en las civilizaciones preincaicas?", options: ["Astronomía", "Registro de información numérica", "Navegación", "Construcción"], correctIndex: 1, explanation: "El quipu era un sistema de cuerdas con nudos que servía para registrar información numérica.", difficulty: "intermediate" },
    { id: 1612, question: "¿Cuál es el período más conocido de la civilización Moche?", options: ["Moche Temprano", "Moche Medio", "Moche Tardío", "Todos son igualmente conocidos"], correctIndex: 1, explanation: "El período Moche Medio es el más conocido por su producción artística y expansión territorial.", difficulty: "intermediate" },
    { id: 1613, question: "¿Qué civilización preincaica se extendió por los Andes centrales y costa sur?", options: ["Tiahuanaco", "Wari", "Nazca", "Moche"], correctIndex: 1, explanation: "El imperio Wari se extendió por los Andes centrales y la costa sur del Perú.", difficulty: "intermediate" },
    { id: 1614, question: "¿Cuál fue el centro ceremonial más importante de los chimúes?", options: ["Chan Chan", "El Brujo", "Túcume", "Sipán"], correctIndex: 0, explanation: "Chan Chan fue la capital del imperio Chimú y la ciudad de adobe más grande del mundo antiguo.", difficulty: "intermediate" },
    { id: 1615, question: "¿Qué civilización desarrolló el sistema de camellones o waru waru?", options: ["Chavín", "Wari", "Tiahuanaco", "Nazca"], correctIndex: 2, explanation: "Los tiahuanacotas desarrollaron el sistema de camellones para la agricultura en alturas.", difficulty: "advanced" },
    { id: 1616, question: "¿Qué civilización preincaica fue conocida por las momias más antiguas del Perú?", options: ["Caral", "Vicus", "Chavín", "Moche"], correctIndex: 1, explanation: "Los restos más antiguos de momificación fueron encontrados en Vicus.", difficulty: "advanced" },
    { id: 1617, question: "¿Qué técnica agrícola usaron los nazca en las tierras áridas?", options: ["Aceros", "Pallareras", "Túneles de irrigación", "Andenes"], correctIndex: 2, explanation: "Los nazca construyeron túneles subterráneos de irrigación llamados puquios.", difficulty: "advanced" },
    { id: 1618, question: "¿Cuál fue la principal función económica de los chimúes en el comercio marítimo?", options: ["Pesca comercial", "Transporte de sal", "Intercambio de metales", "Todos los anteriores"], correctIndex: 3, explanation: "Los chimúes participaban en múltiples actividades económicas incluyendo pesca y transporte.", difficulty: "advanced" },
    { id: 1619, question: "¿Qué simbolismo tenían los geoglifos de Nazca según investigaciones recientes?", options: ["Calendario agrícola", "Mensajes a los dioses", "Señales hidráulicas", "Todas las anteriores"], correctIndex: 3, explanation: "Investigaciones recientes sugieren que los geoglifos cumplían múltiples funciones.", difficulty: "advanced" },
    { id: 1620, question: "¿Qué aporte arquitectónico legó Tiahuanaco a las civilizaciones posteriores?", options: ["Puerta del Sol", "Sistema de silos", "Tecnología de cantería", "Todas las anteriores"], correctIndex: 3, explanation: "Tiahuanaco legó la Puerta del Sol, el sistema de silos y avanzadas técnicas de construcción.", difficulty: "advanced" },
    { id: 1621, question: "¿Qué significado tenía la momia de Sipán para los moches?", options: ["Líder político", "Guerrero sagrado", "Sacerdote", "Mercader"], correctIndex: 1, explanation: "El señor de Sipán fue interpretado como un guerrero sagrado con funciones religiosas y políticas.", difficulty: "advanced" }
