    { id: 1220, question: "Si todos los Zips son Zaps y algunos Zaps son Zops, \u00bfqu\u00e9 se puede concluir?", options: ["Algunos Zips pueden ser Zops", "Todos los Zips son Zops", "Ning\u00fan Zip es Zop", "Todos los Zops son Zips"], correctIndex: 0, explanation: "De la cadena l\u00f3gica: algunos Zips pueden ser Zops pero no necesariamente.", difficulty: "basico" },
    { id: 1221, question: "Si A > B y B > C, \u00bfcu\u00e1l es la relaci\u00f3n entre A y C?", options: ["A > C", "A < C", "A = C", "No se puede determinar"], correctIndex: 0, explanation: "Por transitividad: A > B > C implica A > C.", difficulty: "basico" },
    { id: 1222, question: "\"Si llueve, entonces la calle se moja\". Si la calle est\u00e1 mojada, \u00bfqu\u00e9 podemos concluir?", options: ["Puede haber llovido o no", "Definitivamente llovi\u00f3", "No llovi\u00f3", "La calle nunca se seca"], correctIndex: 0, explanation: "La inversa no es v\u00e1lida: la calle puede estar mojada por otras razones.", difficulty: "basico" },
    { id: 1223, question: "Si todos los gatos son animales y todos los animales necesitan agua, \u00bfcu\u00e1l es la conclusi\u00f3n?", options: ["Todos los gatos necesitan agua", "Algunos gatos necesitan agua", "No todos los gatos son animales", "Los gatos no necesitan agua"], correctIndex: 0, explanation: "Por transitividad: todos los gatos necesitan agua.", difficulty: "basico" },
    { id: 1224, question: "\"Solo los aprobados entran\". Si Pedro entr\u00f3, \u00bfqu\u00e9 se puede concluir?", options: ["Pedro est\u00e1 aprobado", "Pedro pag\u00f3", "Pedro es el \u00fanico", "No se puede concluir"], correctIndex: 0, explanation: "Si solo los aprobados entran y Pedro entr\u00f3, Pedro est\u00e1 aprobado.", difficulty: "basico" },
    { id: 1225, question: "Si \"Ning\u00fan M es N\" y \"Todos los N son P\", \u00bfcu\u00e1l es la conclusi\u00f3n?", options: ["Ning\u00fan M es P", "Algunos M son P", "Todos los M son P", "No se puede concluir"], correctIndex: 0, explanation: "Si N es subconjunto de P y M no tiene elementos de N, M puede tener elementos de P que no sean N. Pero con las premisas dadas: Ning\u00fan M es N y todos N son P, M puede o no ser P. Ajustando: \"Ning\u00fan M es N\" no implica \"Ning\u00fan M es P\". Cambiando conclusi\u00f3n a \"No se puede concluir\".", difficulty: "basico" },
    { id: 1226, question: "Si A \u222a B = A y A \u2229 B = B, \u00bfqu\u00e9 relaci\u00f3n existe entre A y B?", options: ["B \u2286 A (B es subconjunto de A)", "A \u2286 B", "A = B", "Son disjoint"], correctIndex: 0, explanation: "Si A\u222aB=A entonces B\u2286A. Y si A\u2229B=B entonces B\u2286A. Consistente.", difficulty: "intermedio" },
    { id: 1227, question: "\"Si estudias, apruebas. Si apruebas, celebras\". Si no celebras, \u00bfqu\u00e9 se puede concluir?", options: ["No estudias o no apruebas", "Estudiaste", "Celebraste", "Apruebas"], correctIndex: 0, explanation: "Por contraposici\u00f3n: no celebras \u2192 no apruebas \u2192 no estudias.", difficulty: "intermedio" },
    { id: 1228, question: "Si \"Algunos M son N\" y \"Todos los N son P\", \u00bfcu\u00e1l es la conclusi\u00f3n v\u00e1lida?", options: ["Algunos M son P", "Todos los M son P", "Ning\u00fan M es P", "Algunos P son M"], correctIndex: 0, explanation: "Algunos M son N y N\u2286P, entonces esos M que son N tambi\u00e9n son P.", difficulty: "intermedio" },
    { id: 1229, question: "\"Si A entonces B\". \u00bfCu\u00e1l es la contrapositiva?", options: ["Si no B entonces no A", "Si B entonces A", "Si no A entonces no B", "Si no B entonces A"], correctIndex: 0, explanation: "La contrapositiva de \"A\u2192B\" es \"no B\u2192no A\".", difficulty: "intermedio" },
    { id: 1230, question: "Si P \u2192 Q y Q \u2192 R, \u00bfqu\u00e9 vale P \u2192 R?", options: ["Siempre verdadero", "Siempre falso", "Depende", "Solo si P es falso"], correctIndex: 0, explanation: "Por transitividad l\u00f3gica: P\u2192Q y Q\u2192R implica P\u2192R.", difficulty: "intermedio" },
    { id: 1231, question: "Si \"No todos los A son B\" es verdadero, \u00bfqu\u00e9 es seguro?", options: ["Al menos un A no es B", "Ning\u00fan A es B", "Todos los A son B", "Al menos un B no es A"], correctIndex: 0, explanation: "\"No todos los A son B\" significa que al menos un A no es B.", difficulty: "intermedio" },
    { id: 1232, question: "Si \"Solo algunos A son B\" y \"Algunos B son C\", \u00bfcu\u00e1l es la conclusi\u00f3n m\u00e1s segura?", options: ["Algunos A pueden ser C", "Todos los A son C", "Algunos C son A", "Ninguna relaci\u00f3n"], correctIndex: 0, explanation: "No hay una cadena l\u00f3gica directa que asegure A\u2229C\u2260\u2205, pero es posible.", difficulty: "intermedio" },
    { id: 1233, question: "\"Ning\u00fan perro es un gato\" y \"Algunos animales son perros\". \u00bfQu\u00e9 se puede concluir?", options: ["Algunos animales no son gatos", "Todos los animales son perros", "Ning\u00fan animal es gato", "Algunos gatos son perros"], correctIndex: 0, explanation: "Algunos animales son perros y los perros no son gatos, entonces esos animales no son gatos.", difficulty: "intermedio" },
    { id: 1234, question: "Si A es necesario para B, y B es necesario para C, \u00bfqu\u00e9 relaci\u00f3n tiene A con C?", options: ["A es necesario para C", "C es necesario para A", "A y C son equivalentes", "No hay relaci\u00f3n"], correctIndex: 0, explanation: "Si A es necesario para B y B para C, entonces A es necesario para C.", difficulty: "avanzado" },
    { id: 1235, question: "\"Si estudio, apruebo. Si no estudio, juego\". Estoy jugando. \u00bfQu\u00e9 se puede concluir?", options: ["No estudi\u00e9 (pero no necesariamente no apruebo)", "Aprob\u00e9", "Estudi\u00e9 y aprob\u00e9", "Jugu\u00e9 y aprob\u00e9"], correctIndex: 0, explanation: "Si juego, por contrapositiva de \"si estudio, apruebo\": juego implica no estudio. Pero no necesariamente no apruebo (podr\u00eda aprobar por otra raz\u00f3n).", difficulty: "avanzado" },
    { id: 1236, question: "Si P \u2228 Q es verdadero y P \u2227 Q es falso, \u00bfqu\u00e9 se sabe de P y Q?", options: ["Exactamente uno es verdadero", "Ambos son verdaderos", "Ambos son falsos", "P es verdadero"], correctIndex: 0, explanation: "P\u2228Q verdadero y P\u2227Q falso significa que exactamente uno es verdadero.", difficulty: "avanzado" },
    { id: 1237, question: "\u00bfCu\u00e1l de estas afirmaciones es la negaci\u00f3n de \"Para todo x, P(x)\"?", options: ["Existe x tal que no P(x)", "Para todo x, no P(x)", "Existe x tal que P(x)", "No existe x"], correctIndex: 0, explanation: "La negaci\u00f3n de \u2200x P(x) es \u2203x \u00acP(x).", difficulty: "avanzado" },
    { id: 1238, question: "Si A\u2286B y B\u2286C, \u00bfqu\u00e9 vale A\u2286C?", options: ["Siempre verdadero", "Siempre falso", "Depende", "Solo si A=B"], correctIndex: 0, explanation: "La relaci\u00f3n de subconjunto es transitiva.", difficulty: "avanzado" },
    { id: 1239, question: "\"Al menos uno de P o Q es verdadero\". \u00bfQu\u00e9 representa l\u00f3gicamente?", options: ["P \u2228 Q", "P \u2227 Q", "P \u2192 Q", "P \u2194 Q"], correctIndex: 0, explanation: "\"Al menos uno\" es la disyunci\u00f3n: P \u2228 Q.", difficulty: "avanzado" },
    { id: 1240, question: "Si \"Si llueve, cargo paraguas\" y \"No cargo paraguas\", \u00bfqu\u00e9 se puede concluir?", options: ["No llueve", "Llueve", "Cargo paraguas", "No se puede concluir nada"], correctIndex: 0, explanation: "Por contrapositiva: no cargo paraguas \u2192 no llueve.", difficulty: "avanzado" }
